function e(){return(e=r(()=>{i={APP:{about:{description:"Su de mi",link:"/about",moreInfo:"More info"},actions:{click:"S\xecca",tap:"Toca"},contact:"Contato",cookies:{accept:"Aceta",message:"D\xf2paro Google Analytics par contar le vixite de le p\xe0xene. Sto chi d\xf2para cookie. Te se d'acordo co el traciamento anon\xecmo de le stat\xecsteghe? <small><strong>(No se rancura dati persona\u0142i.)</strong></small>",refuse:"No, grasie."},related:"Lig\xe0",featured:"\u0141aori se\u0142esion\xe0",title:"Luis Kr\xf6tz",preferences:"Preferense",language:"L\xe9ngua",pref:{title:"Preferense",done:"Fato",appearance:{title:"Aspeto",desc:"S\xe8rz come che'l sito el se varda",system:{label:"Sistema",sub:"Va dr\xeco a l'OS"},dark:{label:"Scuro",sub:"Modo scuro"},light:{label:"Ciaro",sub:"Modo ciaro"}},motion:{title:"Movimento",desc:"Contro\u0142a animasion e transision",full:{label:"Norma\u0142e",sub:"Movimento conpleto"},reduced:{label:"Ridoto",sub:"Manco movimento"}},closeLabel:"Sara preferense",devTools:{title:"Strumenti da Svi\u0142upador",statsForNerds:"Stat\xecsteghe par i Nerd",statsForNerdsDesc:"FPS dal vivo, r\xe8te, memoria HUD, canton baso a drita",showGrid:"Mostra Gr\xeclia",showGridDesc:"Co\u0142one, margine e \xe0rea masima soraposte a ogni breakpoint",reducedMotion:"Movimento Ridoto",reducedMotionDesc:"Smena animasion e transision"}},carousel:{prev:"E\u0142emento prima",next:"E\u0142emento dopo",ofLabel:"de"},statsHud:{title:"Prestasion",fps:"FPS",cpu:"CPU",memory:"Memoria",network:"R\xe8te",latency:"Latenza",requests:"Richieste",gpu:"GPU"},earthPlayground:"Tera\u0142udo",starField:"Canpo Ste\u0142are",menu:"Men\xf9",close:"Sara",skip:"Laktawan ang nilalaman",loader:{lines:["[SYS_BOOT] INITIALIZING ARCHITECTURE v3.8","[GPU_CORE] ALLOCATING SHADER PIPELINES","[WASM_ENG] THREAD POOL READY: 4 WORKERS","[VRAM_MGR] POOL & PURGE PROTOCOL ENGAGED","[RUNTIME] SYSTEM VERIFIED: LAUNCHING INTERFACE"],initWebGpu:"Inisia\u0142izasion de WebGPU",title:"Luis Kr\xf6tz",stages:["Cargando i testi de \u0142a interfacia","Cargando font e media","Montando i componenti","Preparando \u0142e p\xe0xene","Interfacia pronta"]},engine:{title:"Motore IA",npu:"Hardware NPU ativo",gpu:"Hardware GPU ativo",wasm:"Worker WASM ativo",on:"ON",off:"SPENTO",controls:"Stat\xecsteghe e controi de prestasion"},media:{preview:"Anteprima media",videoControls:"Controi video",autoplay:"Autoriprodusion video",goToSlide:"Va a \u0142a diapositiva",toExpand:"par slargar"},awards:{nextAward:"Tenpo fin a'l prosimo premio",legalNav:"Legale"},sitePreferences:"Preferense del sito: tema e movimento",loading:"Cargando",notFound:"P\xe0xena no cata",notify:{title:"Aviso",error:"Algo sali\xf3 mal",loadFailed:"Una secci\xf3n no pudo cargar",dismiss:"Descartar notificaci\xf3n"},animations:"Riferimento Animassion"},components:{contact:{line1:[{description:"Posta",link:"mailto:luis.krotz@gmail.com"},{description:"Te\u0142efono",link:"tel:+55(51)982-274-782"},{description:"Linkedin",link:"https://www.linkedin.com/in/luis-kr\xf6tz?locale=en_US"},{description:"Github",link:"https://github.com/LuisKrotz"}],line2:[{description:"Po\u0142\xectega de \u0142a Privacy",link:"/privacy-policy"},{description:"GDPR",link:"/gdpr"},{description:"Condision de Uxo",link:"/terms-of-use"}],title:"Contato"},"legal-footer":{links:[{link:"/",page:"Casa"},{link:"/privacy-policy",page:"Po\u0142\xectega de \u0142a Privacy"},{link:"/gdpr",page:"GDPR"},{link:"/terms-of-use",page:"Condision de Uxo"},{link:"/tln/lisensa",page:"Licensa"}]},media:{close:"Sara",toOpen:"par v\xe8rzar",audioNote:"Sto video el prexenta audio in inglexe \u2014 no ghe xe tradussion orixenal disponibil."},related:{note:"Tuti i media de sto dominio i xe stai tirai f\xf2ra come screenshot da URL p\xf9blichi e/o ambienti de svi\u0142upo \u0142ocai co dati de prova sensa va\u0142or de produsion. Tuti i deriti de propriet\xe0 inte\u0142etua\u0142e i xe dei propietari de ogni progeto. Sto portafoglio el mostra so\u0142o el me contributo t\xe8cnego persona\u0142e come svi\u0142upador; la partesipasion de altri menbri de l'\xe8quipe podar\xeca no \xe8sar detajada del tuto par via de \u0142a portada del progeto e dei record st\xf2richi.",path:"/portfolio/",projects:[{featured:!0,link:"metcha",page:"Metcha"},{featured:!1,link:"transa",page:"Transa"},{featured:!0,link:"brazilian-leather",page:"Brazilian Leather"},{featured:!1,link:"mor",page:"Mor"},{featured:!1,link:"coza",page:"Coza"},{featured:!0,link:"melissa",page:"Melissa"},{featured:!1,link:"minimelissa",page:"Minimelissa"},{featured:!1,link:"aboutmarco",page:"Marco Almeida"},{featured:!1,link:"clinica-de-desenvolvimento-nathalia-bond",page:"Nathalia Bond"},{featured:!1,link:"cecerele",page:"Cecerel\xea"},{featured:!1,link:"vibra",page:"Vibra"},{featured:!1,link:"genesysinf-sageweb",page:"Genesysinf"}],title:"Lig\xe0",socials:[{link:"mailto:luis.krotz@gmail.com",network:"Posta"},{link:"tel:+55(51)982-274-782",network:"Te\u0142efono"},{link:"https://www.linkedin.com/in/luis-kr%C3%B6tz/?locale=en_US",network:"Linkedin"},{link:"https://github.com/LuisKrotz",network:"Github"}]},"lang-dialog":{title:"L\xe9ngua",close:"Sara se\u0142etor de l\xe9ngua"},"source-code":{label:"CODIXE SORGENTE DEL PROJETO:",link:"Git",credit:"Svi\u0142upo, UI e design creativo, produsion de contenuti, scritura, tradusion, ingegneria, ingegneria UX, revision, concetua\u0142isasion, produsion, devOps e manutension de sta piataforma, tuto fato da Luis Kr\xf6tz.",rights:"Copyright \xa9 {year} Luis Kr\xf6tz"},"preferences-modal":{title:"Preferense",close:"Sara preferense"},"docs-portal":{title:"Documentasion detajada dei projeti",description:"Dispon\xecbi\u0142e so\u0142o in inglexe",copyToast:"Sta p\xe0gina no \u0142a permete copiar \u2014 varda github par descargar el codaxe."},animations:{"progress-bar":{alt:"Barra de avansamento de rota che scor\xe9a sul bordo de sora durante \u0142a navegasion",longdesc:"\u0141a bara soti\u0142e de avansamento fissada sul bordo de sora del viewport. Animasion: un transform scaleX scor\xe9a \u0142a bara da xero a circa setanta par sento in qua\u0142o secondo finch\xe9 el canbio de rota xe in corso, dopo \u0142a riva a sento par sento e \u0142a sfuma sul posto cuando \u0142a vista de destinasion xe pronta \u2014 no\u0142a torna mai indr\xeco in modo visibi\u0142e. Trigger: partise a ogni navigasion interna e finise cuando \u0142a nova vista xe montada. Tecnologia: transision CSS su transform e opacity guidae da do clase de stato \u2014 xero JavaScript par frame. Scopo: dir che una transision de p\xe0xina xe in corso, in sti\u0142e nprogress."},"burger-button":{alt:"Boton del men\xf9 hamburger co animassion morph liquida",longdesc:"El boton del men\xf9 hamburger in alto a destra de ogni p\xe0gina. Animassion: morph liquido tra l'icona a tre linee e la X de s\xe0r\xf2 \u2014 i trati i se piega e i se fon de come fluido invesse de xirar rigidi. Trigger: el scatta al clic/tocco quando el men\xf9 el se verze e el se invertisse quando el se sera; l'hover el canbia la tension dei trati. Tecnologia: widget canvas guid\xe0 da Rust/WASM (fragment shader WebGL), co variante worker WebGPU/OffscreenCanvas e fallback CSS puro. Scopo: comunicar el st\xe0 verto/ser\xe0 del men\xf9 co na transission t\xe0tile e f\xecsica."},"nav-menu-background":{alt:"Sfondo anim\xe0 a schermo intiero del men\xf9 co canpo de contorni fluido",longdesc:"El sfondo a schermo intiero depint dr\xeco l'overlay del men\xf9 de navigassion. Animassion: un canpo de contorni fratai in lento movimento \u2014 strati de rumore fbm i deriva e i se remodela continuamente, come miragio de calore o plasma. Trigger: el parte quando el men\xf9 hamburger el se verze, el se ferma e el vien scart\xe0 al ser\xe0. Tecnologia: fragment shader WebGL (fbm in GLSL) su canvas dedic\xe0, co variante WebGPU/OffscreenCanvas su worker e fallback gradiente CSS st\xe0tico. Scopo: dar al men\xf9 na profondit\xe0 atmosf\xe9rica viva invesse de un pan\xe8 a tinta piata."},"nav-menu":{alt:"Vosi del men\xf9 de navigassion co entrata ascendente scajonada",longdesc:"L'overlay del men\xf9 de navigassion che el se verze dal boton hamburger. Animassion: ogni voze la entra co salita e fade scajonadi (nav-menu-item-in), licando de qualche pixel in alto mentre la comparisse; un sbarluso membrana/plasma el deriva sul pan\xe8 in loop lento. Trigger: l'entrata la parte na olta per vert\xf9ra, sequensiada da sora a soto; la deriva de la membrana la gira in loop fin che el men\xf9 el xe verto. Tecnologia: keyframe CSS co delay per voze, zero JavaScript per frame. Scopo: sequensiar i link cuss\xec l'ocio i li leze in \xf3rdene invesse de un flash \xf9gnego."},"nav-flag":{alt:"Icona bandiera de la lengua co animassion onda e entrata",longdesc:"El picenin canvas bandiera tac\xe0 a l'eticheta de la lengua inte la bara de navigassion. Animassion: la tea de la bandiera la ondula co un ripple sinusoidal e el glifo intiero el entra in scala (nav-flag-in) quando la nav la monta o la lengua la canbia. Tecnologia: widget canvas che el rende la bandiera proceduralmente (le bandiere de paesi spartii le xe composte), co el keyframe CSS che el gestisse l'entrata. Scopo: segnar la lengua ativa co na bandiera che la p\xe0r tea, no na icona piata."},"switch-slider":{alt:"Interutor de preferensa co licada liquida del pollice",longdesc:"I interutori on/off drento el di\xe0logo dele preferense (aspeto, movimento, efeti). Animassion: el pollice el lic\xe0 longo el binario co slongamento liquido \u2014 el se slonga durante el tragito e el torna a riposo, come na gosa. Trigger: el scatta al clic/tocco o a l'alternansa da tastiera. Tecnologia: widget WebGL/canvas (guid\xe0 da Rust/WASM) che el depinze binario e pollice, co fallback CSS par motori sensa WebGL. Scopo: render t\xe0tile el st\xe0 binario e confermar che l'alternansa la xe avenua."},"theme-slider":{alt:"Seletor tema co licada orbitale d\xec/note",longdesc:"L'interutor tema ciaro/scuro inte el di\xe0logo preferense e inte la navigassion. Animassion: el pollice el viaja come un corpo orbitale \u2014 un disco d\xec/note el traversa el binario mentre glifi sol/luna i fa crossfade drento de lu. Trigger: el scatta a l'alternansa; anca na olta al caricamento quando el tema salv\xe0 el difarisse dal predefin\xec. Tecnologia: widget WebGL/canvas (guid\xe0 da Rust/WASM) co fallback CSS. Scopo: contar el canbio tema come na alba/tramonto invesse de un flip binario."},"close-button":{alt:"Boton sera co inpianto liquido e X xiratoria",longdesc:"El boton circular de s\xe0r\xf2 dei modal e del lightbox media espanso. Animassion: in hover un inpianto liquido el sale drento el cerchio mentre i trati de la X i xira e i se tende; a la presion l'inpianto el scata. Trigger: hover/focus el lo arma, la presion la lo libera. Tecnologia: widget WebGL/canvas (guid\xe0 da Rust/WASM) co un semplice boton CSS soto par motori sensa WebGL. Scopo: dar al s\xe0r\xf2 na sensassion f\xecsica e sodisfasente de presion."},skeleton:{alt:"Sch\xe8letro de caricamento co sele in morph e shimmer",longdesc:"I sch\xe8letri placeholder mostrai d\xf3ndo el contenuto el sta ancora cargando (figure media, bl\xf2chi de testo, tile de progeto). Animassion: sele de glifo i fa morph tra forme 0/1 mentre un sbarluso a gradiente el traversa la superficie da sinistra a destra (skeleton-shimmer). Trigger: el gira continuamente mentre el contenuto el carica, po el consegna a l'elemento real. Tecnologia: widget canvas (morph de sele guid\xe0 da Rust/WASM) pi' el keyframe CSS dello shimmer. Scopo: segnalar \"el contenuto el riva\" co un movimento che l'anticipa el layout invesse de uno spinner."},"intro-loader":{alt:"Loader de introdussion co anei contrarotanti e progresso",longdesc:"El loader de aviamento a schermo intiero mostr\xe0 mentre i primi asset del sito i carica. Animassion: do anei i xira in diressioni oposte (intro-loader-spin-cw/ccw) atorno a un contador de percentuale e mesagi de fase localissadi. Trigger: el gira dal caricamento de la p\xe0gina fin che el bundle de aviamento el xe pronto, po l'intiero loader el sfunia e el se lea via. Tecnologia: keyframe CSS che i fa xirar i anei; el JS el riporta so\u0142o el progresso. Scopo: tener el primo paint vivo e leg\xecbile durante la sequensa de aviamento tier/polyfill."},"site-toast":{alt:"Toast de notifega che el lic\xe0 dal canton",longdesc:"El picenin toast de notifega che el comparisse in un canton dello schermo par eventi come conferme de copia e assioni sui cookie. Animassion: el lic\xe0 dal bordo mentre el sfunia in alto (site-toast-in), el tien, po el ese licando indrio co fade. Trigger: scaten\xe0 da eventi de l'app (copia, avixo storage, notifega de test). Tecnologia: keyframe CSS in entrata e un modificador --closing in essita. Scopo: tirar l'ocio su un mesagio transitorio sensa blocar l'interassion."},"mosaic-burn":{alt:"Titolo del tile portfolio che el brusa in brase e el se ricompone",longdesc:"El testo del titolo sui tile del mosaico dei laori in evidensa. Animassion: in hover le letere del titolo le entra in combusti\xf3n \u2014 bordi erosi, scie de brusadura e partic\xe8le de brasa incandescente le consuma i glifi colona par colona, e le letere le se ricostruisse dal basso a l'alto travers el stesso canpo de fogo quando el puntador el ese o l'hover el canbia bersagio. Trigger: hover del puntador sul tile. Tecnologia: simulassion particelare in Rust/WASM (crate mosaic-burn) che la eseguisse el modelo erode/scorch/ember su canvas; un percorso 2D-canvas el rende el stesso canpo quando la rota GPU la xe smorta \u2014 tuti do i condivide na simulassion deterministica. Scopo: trasformar el semplice hover inte l'efeto fogo firma del sito."},"mosaic-tile":{alt:"Tile portfolio che el lic\xe0 in novo slot a mo\u0142a + sbarluso sul bordo",longdesc:"Le card de progeto inte el mosaico dei laori in evidensa. Animassion: quando na card la se espande in hover, i vesini spostadi i lic\xe0 intei novi slot co na mo\u0142a smorsada \u2014 na curva org\xe0nica de overshoot e assestamento (mo\u0142a sintetissada in CSS linear()) invesse de una licada lineare; un sbarluso el percorre periodicamente el bordo de ogni tile. Trigger: el repack da hover el anima i tile spostadi; el sbarluso del bordo el gira in loop lieve. Tecnologia: pack masonry in JS + transission CSS su transform; el sbarluso el xe un passagio a anelo su canvas. Scopo: tener la par\xe9 liquida e viva mentre la se ri\xf3rdena."},"media-progressive":{alt:"Imagine media che la pasa da sfocada in basa qualit\xe0 a nitida in alta",longdesc:"Ogni figura media del sito (imagini e video dei progetti). Animassion: un placeholder a basa risolussion el depinze prima, po el fa morph verso l'asset a alta risolussion decodific\xe0 \u2014 el layer in alta el se resolve dallo st\xe0 sfoc\xe0/ingrand\xec de la thumb invesse de lampegiar, cuss\xec l'ocio el leze na nitidessa continua. Trigger: el parte quando la figura la entra inte la viewport (IntersectionObserver) e l'asset el finisse el decode inte el pool WASM. Tecnologia: decode imagine WASM fora dal thread prinsipale, swap a blob-URL e morph in CSS/canvas. Scopo: render el caricamento progressivo come l'imagine che la entra a f\xf3co, no na sostitussion seca."},"glitch-portrait":{alt:"Retrato About co animassion de corussion glitch VHS",longdesc:"L'imagine del retrato inte la session About. Animassion: corussion periodica stil VHS \u2014 roli de scanline, separassion dei canali, spostamenti de bl\xf2chi e bande de rumore i spasa brevemente la foto prima che la torni neta. Trigger: la gira su un timer casuale fin che la session la xe sullo schermo. Tecnologia: passagio de fragment shader WebGL su la texture del retrato co fallback canvas. Scopo: dar al retrato na personalit\xe0 viva da video an\xe0logico, in linea co l'estetica t\xe8cnica del sito."},"divider-sheen":{alt:"Divisor del footer co un sbarluso de luse viajante",longdesc:"I divisori hairline che i separa sessioni de p\xe0gina e colone del footer. Animassion: na banda morbida de luse la viaja lentamente longo el fil, spazando da un capo a l'altro in loop continuo. Trigger: la gira continuamente fin che el divisor el xe sullo schermo. Tecnologia: widget canvas che el depinze la linea pi' la banda a gradiente in movimento. Scopo: elevar na riga st\xe0tica a un detagio sutile e vivo."},"text-draw":{alt:"Testo che el se desegna letera par letera come manoscrito",longdesc:"Titoli de session, link e didascalie co el tratamento draw-text in tuto el sito. Animassion: ogni caratere el xe desegn\xe0 stil tratto de pena in \xf3rdene de let\xf9ra \u2014 i trati i se scrive sequensialmente come caligraf\xeca o plotter, co ragrupamento opsionale par paro\u0142a. Trigger: el parte quando l'elemento el entra inte la viewport (IntersectionObserver, trigger viewport) o su dispatch esplicito. Tecnologia: desegno instansi\xe0 par caratere su canvas (widget text-draw in Rust/WASM) co fallback keyframe CSS (char-draw/word-draw). Scopo: far sembrar i titoli autografadi \u2014 scriti avanti a ti invesse de timbradi."},"ring-sheen":{alt:"Bordo tile co sbarluso che el viaja atorno a l'anelo",longdesc:"I contorni de bordo sui tile del mosaico e dei progetti coreladi. Animassion: na banda de sbarluso la viaja atorno a l'anelo del bordo del tile come luse che la lic\xe0 su na cornise, in loop periodico lento. Trigger: la gira in loop fin che el tile el xe vis\xecbile; la se intensifica in hover. Tecnologia: passagio a anelo su canvas conposto sora el bordo del tile. Scopo: tener vive le grije de card st\xe0tiche co un riflesso anbientale econ\xf2mico."},"corner-brackets":{alt:"\xc0ngui de boton che i espande in parentesi su hover",longdesc:"Le decorassioni a parentesi angulari sui botoni de assi\xf3n (bare de s\xe0r\xf2, CTA). Animassion: le cuatro parentesi angulari le se espande verso fora e le se ilumina in hover, po le se contrae \u2014 come un reticolo de mesa a f\xf3co de fotoc\xe0mera che el scata. Trigger: hover/focus sul boton. Tecnologia: picenin widget canvas par boton (desegno instansi\xe0 de parentesi) co fallback a transission CSS. Scopo: comunicar interativit\xe0 co un indisio de focus preciso e strumentale."},"scene-3d":{alt:"Sena 3D interativa de canpo stelare e tera",longdesc:"Le sene 3D a schermo intiero \u2014 l'esperimento star-field (corpi celesti in \xf3rbita co etichete dosier) e el playground de la tera (pianeta che el xira co controi de \xf3rbita). Animassion: movimento continuo ispir\xe0 a la f\xecsica \u2014 mec\xe0nica orbitale, rotassion, paralasse al movimento de c\xe0mera e transissioni tra corpi. Trigger: la gira par tuto el tempo che la sena la xe sullo schermo; puntador/toco el orbita la c\xe0mera. Tecnologia: three.js su WebGL/WebGPU co el laoro par frame mantegnuo su la GPU. Scopo: la vetrina 3D in tempo real firma del sito."},"genie-modal":{alt:"Media espanso che el se verze in warp liquido verso el lightbox",longdesc:"El lightbox media espanso che el se verze cicando su un'imagine o un video de progeto. Animassion: el media el se deforma tra el ret\xe0ngolo de la figura cicada e la scato\u0142a del modal a schermo intiero come un fogio liquido \u2014 bande orisontali le ritarda, le se incurva e le se stira travers un canpo genie mentre partic\xe8le de vapor le se staca da la piega in movimento; el stesso canpo el lo colasa indrio al ser\xe0. Trigger: clic/toco par v\xe8rzar, boton sera o Escape par colasar. Tecnologia: widget WebGPU/Rust mesh-warp + partic\xe8le su un worker fora dal thread prinsipale quando abilit\xe0, un renderer 2D-canvas a bande sensa alocassioni par frame dapartuto altro, e un keyframe CSS de zoom come \xf9ltima risorsa. Scopo: sostituir un seco scale-fade co na transission f\xecsica stil dock macOS."},carousel:{alt:"Caroselo premi che el lic\xe0 co momentum e bara de progresso",longdesc:"El caroselo orisontale dei premi inte el footer de la home. Animassion: le vosi le lic\xe0 co momentum e le fa snap in posission; na bara de progresso la se impienisse longo el binario, un tratto de autoplay el anima el timer e i controi de assi\xf3n i comparisse. Trigger: gesti de strasinamento/scroll, controi precedente/sucesivo e el timer de autoplay. Tecnologia: scroll snapping nativo pi' springs in JS e keyframe CSS par el chrome. Scopo: far sembrar el sfogiamento de la striscia dei premi come mesclar carte f\xecsiche."},"about-text":{alt:"Par\xe0grafo About che el rivela i so carateri un a un",longdesc:"I par\xe0grafi de la biograf\xeca inte la session About. Animassion: el testo el se rivela caratere par caratere inte l'\xf3rdene dele frasi \u2014 ogni letera la sfunia/la se move inte el so tempo, cuss\xec el par\xe0grafo el p\xe0r scrivarse da so\u0142o. Trigger: el parte quando la session la entra inte la viewport. Tecnologia: JS el sequensia span par caratere co timing guid\xe0 da rAF; el CSS el gestisse la transission par caratere. Scopo: dar a la bio na cadensa da m\xe0china da scriver/vose in linea co i titoli draw-text."},"related-tile":{alt:"Card progeto corel\xe0 che la se s\xf3lza e la zooma su hover",longdesc:"Le card dei progetti coreladi in fondo a le p\xe0gine de progeto. Animassion: in hover la card la se s\xf3lza, la so imagine la zooma dolcemente e t\xedtulo/descrission i lic\xe0 su \u2014 tuto co easing a mo\u0142a smorsada (springs sintetissadi in CSS linear()) cuss\xec el movimento el pasa legermente e el se assesta in modo org\xe0nico; un sbarluso el spasa el bordo de la card. Trigger: hover/focus del puntador. Tecnologia: transissioni CSS su transform/opacity guidade da curve a mo\u0142a. Scopo: render l'affordance de navigassion f\xecsica e invitante."},"note-dot":{alt:"Marcador de nota che el pulsa dolcemente",longdesc:"I picenini marcadori de nota/ponto usadi inte le p\xe0gine internals (documentassion e interne de progeto). Animassion: el ponto el pulsa dolcemente \u2014 un loop respirante de scala e fade. Trigger: el gira in loop continuo sullo schermo. Tecnologia: un keyframe CSS (note-dot-pulse). Scopo: segnar l'elemento come anotassion viva sensa esiger atension."},"body-glow":{alt:"Sbarluso anbientale de la p\xe0gina che el deriva dr\xeco el contenuto",longdesc:"El sbarluso de sfondo anbientale dr\xeco el contenuto de la p\xe0gina. Animassion: un gran gradiente radiale morbido el deriva lentamente travers el documento, canbiando posission e intensit\xe0 in un loop longo. Trigger: el gira continuamente su ogni p\xe0gina. Tecnologia: un keyframe CSS (body-glow-drift) che el anima un layer de sfondo fiso \u2014 zero JavaScript. Scopo: dar atmosfera e profondit\xe0 al tema scuro invesse de un sfondo piato."}}},pages:{HOME:{archive:"D\xe0 na ociada",explore:"Varda",featured:"\u0141aori se\u0142esion\xe0",message:"Laori sern\xeci",portfoliolist:[{description:"Costruzione e scalabilit\xe0 del Dell Design System a supporto di oltre 500 prodotti aziendali.<br>Operando come Software Engineer, Agile Champion, Tech Lead e Support Analyst su flussi di lavoro interfunzionali di ingegneria, accessibilit\xe0, contenuti, design e sviluppo guidato da specifiche AI per ottenere creazione fluida di componenti multi-framework, parit\xe0, supporto e manutenzione su Vanilla, React, Angular e Visualizzazione Dati per un design e un'esperienza utente unificati.",height:["769","793"],image:"dell-design-system",label:"Dell Design System",link:"dell-design-system",width:["1230","889"],featured:!0},{description:"N'oraco\u0142o del coiame, del dixegno e de \u0142a cultura.<br>Svi\u0142up\xe0 a Transa Inc. in co\u0142aborasion co Leather Naturally, \u0142a p\xecataforma \u0142a conta \u0142e store pi be\u0142e del mondo del dixegno, de l'arte, de \u0142a moda e del sti\u0142e de vita, metendo in \u0142uxe \u0142e parsone che \u0142e fas \u0142a cultura creativa.",height:["750","301"],image:"metcha",label:"Metcha",link:"metcha",width:["1915","768"],featured:!0},{description:"Un portale de marca che \u0142iga tuto cue\u0142o che g\xe0 da vedar co Melissa.<br>Ghe jera feed dei social e contenuto orixina\u0142e fato a Transa Inc.",height:["799","320"],image:"melissa",label:"Melissa",link:"melissa",width:["1920","768"],featured:!0},{description:"Progeto svi\u0142up\xe0 a Transa Inc. par el Grupo Grendene come cana\u0142e dedic\xe0 a \u0142a marca Mini Melissa.<br>El sito el gav\xe9a un feed de contenuto e un feed socia\u0142e co scroll infinito, dando contenuto escluxivo Mini Melissa. Ativo dal 2018 al 2020.",height:["799","322"],image:"minimelissa-cropped",label:"Mini melissa",link:"mini-melissa",width:["1905","768"],featured:!1},{description:"Progeto svi\u0142up\xe0 a Transa Inc. tra na sociedade tra CICB e Apex-Brasil.<br>Un portale par el Coiame Braxi\u0142ian, che ciapa dentro siti come Brazilian Leather, CICB, CSCB e Leather Law.",height:["850","340"],image:"brazilian-leather",label:"Brazilian leather",link:"cicb",width:["1920","768"],featured:!0},{description:"Progeto svi\u0142up\xe0 a Transa Inc. co el fin de far na esperiensa ve\u0142ose e be\u0142a che \u0142iga i cana\u0142i e \u0142a comunit\xe0 MOR inte 'n so\u0142o posto.",height:["798","319"],image:"mor",label:"Mor",link:"mor",width:["1920","768"],featured:!1},{description:"Progeto svi\u0142up\xe0 a Transa Inc. dal 2017 al 2019.<br>\u0141a p\xe0xena prinsipa\u0142e de Coza jera un feed de contenuto par \u0142a marca, co art\xecco\u0142i, ga\u0142erie, foto e \u0142ink al negozio on\u0142ine.",height:["794","318"],image:"coza",label:"Coza",link:"coza",width:["1920","768"],featured:!1},{description:"El Portafoglio de Marco, svi\u0142up\xe0 come progeto freelance inte'l 2021.<br>El fin prinsipa\u0142e jera dar na UI pixel-perfect co animasion morbide e 'n modo de laorar punt\xe0 a \u0142a prestasion.",height:["1014","406"],image:"aboutmarco",label:"Marco almeida",link:"aboutmarco",width:["1920","768"],featured:!1},{description:"Sito web svi\u0142up\xe0 come progeto freelance inte'l 2021.<br>El sito de Nathalia Bond jera 'n redixegno de que\u0142o vecio, tegnendo \u0142a identit\xe0 vixua\u0142e x\xe0 fata, puntando a rafinarla, e doparando Squarespace come sistema de gestion contenuti fasi\u0142e da mantegnir par l'uxidor fina\u0142e.",height:["640","320"],image:"clinica-nathalia-bond-v3",label:"Nathalia bond",link:"nathalia-bond",width:["1920","960"],featured:!1},{description:"Sito e-commerce svi\u0142up\xe0 come progeto freelance inte'l 2021.<br>Go dixegn\xe0 el negozio de Cecerel\xea so \u0142a p\xecataforma e-commerce Illuria.",height:["640","256"],image:"cecerele",label:"Cecerel\xea",link:"cecerele",width:["1920","768"],featured:!1},{description:"Sito web svi\u0142up\xe0 a e par Transa Inc., fat de 'n feed a scroll infinito, 'n CMS fat so mizura, e p\xe0xene 'join us' e 'cases' che \u0142e resume i progetti svi\u0142upai inte tanti ani.",height:["850","369"],image:"transa",label:"Transa",link:"transa",width:["1920","768"],featured:!1},{description:"Sito web svi\u0142up\xe0 a Transa Inc inte'l 2016 come portale fat par \u0142a marca Vibra.",height:["913","340"],image:"vibra",label:"Vibra",link:"vibra",width:["1920","768"],featured:!1},{description:"Progeto svi\u0142up\xe0 da Genesysinf a Santana do Livramento, Braxi\u0142e: software fisca\u0142e.<br>El progeto el gav\xe9a da portar el software desktop Sage a 'na version web nova.",height:["649","369"],image:"sageweb",label:"Sageweb",link:"sage",width:["1350","768"],featured:!1}]},about:{col1:['Ciao, mi son Luis,<br />\'n Ingegner Software drio \u0142a UX.<br>Anc\xf3ra laoro a Dell so\'l <a href="https://www.delldesignsystem.com" target="_blank">Dell Design System</a>.',"Mi son 'n professionista IT co esperiensa fonda inte'l svi\u0142upo web, l'ana\u0142isi de sistemas e \u0142a gestion de progetti. Me specia\u0142izo a far so\u0142usion dixita\u0142i inovative e efisienti co 'n fort fogo so SEO, acesibi\u0142it\xe0 e prestasion. El me sfondo de programasion ciapa ASP, PHP, C, C#, Pascal, Delphi, JavaScript e SQL, insieme a framework moderni come React, Vue e Angular."],col2:["Go studi\xe0 a UFSM (Universit\xe0 Federa\u0142e de Santa Maria) a Frederico Westphalen, Braxi\u0142e, tegnendo 'na \u0142orea in Tecno\u0142oxia par i Sistemas de Internet, dopo 'n corso post-laurea in <span lang=\"pt-br\">'Gest\xe3o de T.I'</span> (Gestion IT) a UFSM.","El me laoro el xe sempe drio a dar \u0142eayout pixel-perfect: codixe fasi\u0142e da d\xf2parar, ve\u0142ose, be\u0142o e morbido.","M'incanta \u0142e animasion CSS. Go pas\xe0 ani a far \u0142e co\u0142esion de stajon de Melissa cuaxi tute in CSS, e da alora go laor\xe0 co animasion base JS doparando Vue e Lottie, go pro\xe0 Three.js, e de recent go tac\xe0 a vardar svi\u0142upo guid\xe0 da spec\xecfeghe e IA."],frame:'Ciao, mi son Luis,<br />\'n Ingegner Software drio \u0142a UX.<br>Anc\xf3ra laoro a Dell so\'l <a href="https://www.delldesignsystem.com" target="_blank">Dell Design System</a>.',mentions:"Varghe mensi\xf3n:",mention_items:[{description:"Ago. 2013:<br>A UFSM, meso tra i 40 laori mejo del 28\xba JAI",icon:"\ud83c\udfc6",link:"http://coral.ufsm.br/prpgp/images/fomularios-diversos/2013/40-MELHORES-JAI-2013.pdf"},{description:"14 Zugno 2020:<br>Premio Specia\u0142e Kudos CSSDA, d\xe0 a \u0142a prima version de luiskr.com",link:"https://www.cssdesignawards.com/sites/luiskr/37252",media:{height:"1123",path:"awards/cssda-special-kudos-1.svg",width:"794"}},{description:"14 Zugno 2020:<br>Premio Dixegno Inovasion CSSDA, d\xe0 a \u0142a prima version de luiskr.com",link:"https://www.cssdesignawards.com/sites/luiskr/37252",media:{height:"1273",path:"awards/cssda-inn-Luiskr-1.svg",width:"993"}},{description:"14 Zugno 2020:<br>Premio Dixegno UX CSSDA, d\xe0 a \u0142a prima version de luiskr.com",link:"https://www.cssdesignawards.com/sites/luiskr/37252",media:{height:"1132",path:"awards/cssda-ux-Luiskr-1.svg",width:"893"}},{description:"14 Zugno 2020:<br>Premio Dixegno UI CSSDA, d\xe0 a \u0142a prima version de luiskr.com",link:"https://www.cssdesignawards.com/sites/luiskr/37252",media:{height:"1123",path:"awards/cssda-ui-Luiskr-1.svg",width:"886"}},{description:"6 Otobre 2021:<br>Mostr\xe0 so TCG",icon:"\ud83c\udf10",link:"https://www.topcssgallery.com/gallery/luis-krotz/"},{description:"6 Otobre 2021:<br>Ste\u0142a CSSW",link:"https://www.csswinner.com/details/luis-krtz/15699",media:{height:"1132",path:"awards/CSSW-15699-Star-Certificate.svg",width:"993"}},{description:"13 Otobre 2021:<br>Mostr\xe0 so Mindsparkle Mag",icon:"\ud83c\udf10",link:"https://mindsparklemag.com/website/luis-krotz"},{description:"19 Marso 2024:<br>Laoro Public\xe0: 'Desenvolvimento de um prot\xf3tipo para gest\xe3o de conhecimento utilizando Lunr.js'",icon:"\ud83d\udcd8",link:"https://repositorio.ufsm.br/handle/1/32752"}],title:"Su de mi",profilePicture:"https://gravatar.com/avatar/6eff24eea3fb805dfa84837e62ae72ab242378ac3b35bd0e763168f6efe15746?v=1786948200000&size=1280"},GDPR:{title:"GDPR",sections:[{title:"Deriti de Protesion dei Dati",content:["V\xf2io \xe8sar seguro che te se conpletamente al corrente dei to deriti de protesion dei dati. Ogni uxidor el g\xe0 derito a sto chi:","<strong>El derito de aceso</strong>: Te podare dimandar copie dei to dati. No rancuro dati persona\u0142i; son contento de condiv\xecdar cualsiasi dato Google Analytics se ghe ne deo.","<strong>El derito de ret\xecfega</strong>: Te g\xe0 el derito de dimandar \u0142a coretesion de cualsiasi informasion che te cr\xe8 che \u0142a s\xeca sbajada, o de far conpletar informasion inconpleta.","<strong>El derito de scance\u0142asion</strong>: Te g\xe0 el derito de dimandarme de scance\u0142ar i to dati persona\u0142i, serte condision soto.","<strong>El derito de limitar \u0142a e\u0142aborasion</strong>: Te g\xe0 el derito de dimandarme de limitar \u0142a e\u0142aborasion dei to dati persona\u0142i, serte condision soto.","<strong>El derito de opozision a \u0142a e\u0142aborasion</strong>: Te g\xe0 el derito de op\xf3ndarte a \u0142a me e\u0142aborasion dei to dati persona\u0142i, serte condision soto.","<strong>El derito a \u0142a portabi\u0142it\xe0 dei dati</strong>: Te g\xe0 el derito de dimandarme de trasfer\xecr cualsiasi dato che go rancur\xe0 a n'antra organixasion, o diretamente a ti, serte condision soto.",'Se te f\xe8 na dimanda, go un m\xe9xe par responder. Se te v\xf2i eserxitar vargun de sti deriti, contatame via email: <a href="mailto:luis.krotz@gmail.com">luis.krotz@gmail.com</a>.']}]},"privacy-policy":{sections:[{content:["A <a target='_blank' href='/'><span >luiskr</span></a>, aces\xecbi\u0142e da <a target='_blank' href='/'>https://luiskr.com</a>, una de \u0142e me priorit\xe0 prinsipa\u0142i \u0142a xe \u0142a privacy dei me visitadori. Sto documento Po\u0142\xectega de \u0142a Privacy el g\xe0 i tipi de informasion che xe rancur\xe0 e rejistr\xe0 da <a target='_blank' href='/'><span >luiskr.com</span></a> e come che \u0142a d\xf2paro.","Se te g\xe0 dimande in pi o te g\xe0 da sa vere informasion so \u0142a me Po\u0142\xectega de \u0142a Privacy, no ste a esitar a contatarme.","Sta Po\u0142\xectega de \u0142a Privacy \u0142a va\u0142e so\u0142o par \u0142e me ativit\xe0 on\u0142ine e \u0142a xe va\u0142ida par i visitadori del me sito web par cue\u0142o che i g\xe0 spart\xeco e/o rancur\xe0 in <a target='_blank' href='/'><span >luiskr.com</span></a>. Sta po\u0142\xectega no \u0142a xe aplicabi\u0142e a informasion rancur\xe0 fora r\xe8te o via cana\u0142i difarenti da sto sito web."],title:"\u0141a Roba So\u0142ita"},{content:["D\xf2parando el me sito web, te consente a \u0142a me Po\u0142\xectega de \u0142a Privacy e te se d'acordo co i so t\xe8rmini."],title:"Consenso"},{content:["\u0141'informasion persona\u0142e che te vien dimand\xe0 de dar, e i motivi parch\xe9 te vien dimand\xe0, i vegnar\xe0 fadi ciari al punto che te dimando de dar \u0142a to informasion persona\u0142e.","Se te me contate diretamente, podar\xeca ris\xecvar informasion in pi su de ti come el to nome, el to indiriso email, el to n\xf9maro de te\u0142efono, i contenuti del mexaio e/o dei a\u0142egati che te me mande, e cualsiasi altra informasion che te s\xe8rz de dar."],title:"Informasion che rancuro"},{content:["D\xf2paro \u0142a informasion che rancuro in vari modi, come:<ol><li>Dar, operar e mantegnir el me sito web</li><li>Mejorar, persona\u0142izar e slargar el me sito web</li><li>Cap\xecr e ana\u0142izar come che te d\xf2pare el me sito web</li><li>Svi\u0142upar produti, servixi, funsion e funsiona\u0142it\xe0 nove</li><li>Catar e prevegn\xecr fraudi</li><li>File de Log</li></ol>","<a target='_blank' href='/'><span >luiskr.com</span></a> el va dr\xeco a na prosedura standard de d\xf2paro de file de log. Sti file i rejistra i visitadori cuando che i visita i siti web. Tute \u0142e dite de hosting \u0142e fa cus\xec come parte de l'ana\u0142\xecstega dei servixi de hosting. \u0141'informasion rancur\xe0 dai file de log \u0142a ciapa indirisi de protoco\u0142o internet (IP), tipo de navegador, Fornid\xf2r de Servisi Internet (ISP), data e ora, p\xe0xene de riferimento/sort\xeca, e forse el n\xf9maro dei click. Sti chi no i xe \u0142igai a nissuna informasion che \u0142a se poda identificar persona\u0142mente. El fin de \u0142a informasion xe de ana\u0142izar tendense, aministrar el sito, traciar el movimento dei uxidori so'l sito, e rancurar informasion demogr\xe0fega. \u0141a me Po\u0142\xectega de \u0142a Privacy \u0142a xe stada fada co l'agiuto del Privacy Policy Generator e del Disclaimer Generator."],title:"Come che d\xf2paro \u0142a to informasion"},{content:["\u0141a Po\u0142\xectega de \u0142a Privacy de <a target='_blank' href='/'><span >luiskr.com</span></a> no \u0142a va\u0142e par altri anuncianti o siti web. Par cui, ve consejo de consultar \u0142e respetive Po\u0142\xecteghe de \u0142a Privacy de sti servidori de anunci de tersi par informasion pi detajada. Podar\xeca ciapar \u0142e so pr\xe0teghe e istrusion so come desat\xecvar serte opsion.","Te podare desat\xecvar i cookie tra \u0142e opsion del to navegador. Par informasion pi detajada so \u0142a gestion dei cookie co navegadori spez\xecfeghi, varda i respetivi siti dei navegadori."],title:"Po\u0142\xecteghe de Privacy de Tersi"},{content:["Soto el CCPA, tra altri deriti, i consumadori de \u0142a Ca\u0142ifornia i g\xe0 el derito de:","Dimandar che 'n'azienda che rancura dati persona\u0142e del consumador \u0142a reve\u0142a \u0142e categorie e i tochi spez\xecfeghi de dati persona\u0142i che l'azienda g\xe0 rancur\xe0 so i consumadori.","Dimandar che 'n'azienda \u0142a scance\u0142a cualsiasi dato persona\u0142e so'l consumador che l'azienda g\xe0 rancur\xe0.","Dimandar che 'n'azienda che v\xe9nde dati persona\u0142e del consumador, no \u0142a v\xe9nda i dati persona\u0142i del consumador.","Se te f\xe8 na dimanda, go un m\xe9xe par responder. Se te v\xf2i eserxitar vargun de sti deriti, contatame."],title:"Deriti Privacy CCPA (No V\xe8ndeme \u0142a Me Informasion Persona\u0142e)"},{content:["N'antra parte de \u0142a me priorit\xe0 \u0142a xe zontar protesion par i fioi co i d\xf2para internet. Incurajo xenitori e tutori a osservar, partesipar, e/o monitorar e guidar \u0142a so ativit\xe0 on\u0142ine.","<a target='_blank' href='/'><span >luiskr.com</span></a> no rancura consaoromente nissuna Informasion Identificabi\u0142e Persona\u0142e da fioi soto i 13 ani. Se te cr\xe8 che'l to fio g\xe0 d\xe0 sto tipo de informasion so'l me sito web, te incurajo fortemente a contatarme <strong>subito</strong> e far\xf2 el me mejo par catar presto sta informasion."],title:"Informasion dei Fioi"}],title:"Po\u0142\xectega de \u0142a Privacy"},"terms-of-use":{sections:[{content:["El sito web luiskr.com che se cata a <a target='_blank' href='/'>luiskr.com</a> el xe soto LICENSA MIT. <a target='_blank' href='/'>Luiskr.com</a> el xe fato da Luis Kr\xf6tz; serte funsion del Sito podar\xeca \xe8sar sojete a \u0142inee guida, t\xe8rmini o rego\u0142e in pi, che vegnar\xe0 postae so'l Sito in \u0142egame co ste funsion.","Tuti sti t\xe8rmini, \u0142inee guida e rego\u0142e in pi i xe incorporai par riferimento inte sti T\xe8rmini.","Ste Condision de Uxo \u0142e descrive i t\xe8rmini e \u0142e condision legarmente vinco\u0142anti che \u0142e goberna el to uxo del Sito. INTRANDO NEL SITO, TE CONSENTE DE \xc8SAR VINCO\u0141\xc0 DA STI T\xc8RMINI e te rappresente che te g\xe0 l'autorit\xe0 e \u0142a capasit\xe0 de intrar inte sti T\xe8rmini. TE DEVE \xc8SAR ALMANCO DE 18 ANI PAR AC\xc9DAR AL SITO. SE NO TE SE D'ACORDO CO TUTE \u0142e DISPOSISION DE STI T\xc8RMINI, NO INTRAR E/O NO D\xd2PARAR EL SITO.","Sti t\xe8rmini i richiede l'uxo de l'arbitra Sesion 10.2 so base indivixua\u0142e par res\xf2\u0142var dispute e i \u0142imita anca i rimedi dispon\xecbi\u0142i par ti in caxo de disputa."],title:"Version 1.1"},{content:["<strong>Sojeto a sti T\xe8rmini.</strong> <strong><a target='_blank' href='/'>luiskr.com</a></strong> te d\xe0 na \u0142icensa no trasfer\xecbi\u0142e, no escluxiva, revocabi\u0142e, \u0142imitada par ac\xe9dar al Sito so\u0142o par el to uxo persona\u0142e e no comercia\u0142e.","<strong>Serte Restrision.</strong> I deriti aprovai par ti inte sti T\xe8rmini i xe sojeti a ste restrision: (a) no podare v\xe9ndar, afitar, prestar, trasfer\xecr, c\xe9dar, distribu\xecr, ospitar o sfrutar comercia\u0142mente el Sito; (b) no podare canbiar, far \xf2pare derivae, smontar, far conp\xec\u0142a inversa o conp\xec\u0142a roversa de nissuna parte del Sito; (c) no podare ac\xe9dar al Sito par farte 'n sito s\xecmi\u0142e o conpetitivo; e (d) ecezion fada che espresamente dito chi, nissuna parte del Sito podar\xeca \xe8sar copiada, riprodota, distribu\xecda, ripub\u0142icada, scargada, mostrada, postada o trasmisa.","<strong><a target='_blank' href='/'>luiskr.com</a></strong> se riserva el derito de canbiar, susp\xe9ndar o cessar el Sito co o sensa preavixo. Te consente che <strong><a target='_blank' href='/'>luiskr.com</a></strong> no vegnar\xe0 riten\xf9 responsabi\u0142e verso ti o vargun terso par vargun canbiamento, interusion o terminasion del Sito o vargun so parte.","<strong>Nissun Suporto o Mantegnimento.</strong> Te consente che <strong><a target='_blank' href='/'>luiskr.com</a></strong> no g\xe0 nissun ob\u0142igo de darti suporto in \u0142egame co'l Sito.","Ecezion fada che'l Conten\xf9 Uxidor che te podare dar, te se consapevo\u0142e che tuti i deriti de propriet\xe0 inte\u0142etua\u0142e, ciapando deriti d'autor, breveti, marcas e segr\xecti comercia\u0142i, inte'l Sito e inte'l so conten\xf9, i xe propriet\xe0 de <strong><a target='_blank' href='/'>luiskr.com</a></strong> o dei fornidori de <strong><a target='_blank' href='/'>luiskr.com</a></strong>. Varda che sti T\xe8rmini e l'aceso al Sito no i te d\xe0 nissun derito, t\xecto\u0142o o interese so o verso nissun derito de propriet\xe0 inte\u0142etua\u0142e, ecezion fada par i deriti de aceso \u0142imitai espresai inte \u0142a Sesion 2.1. <strong><a target='_blank' href='/'>luiskr.com</a></strong> e i so fornidori i se riserva tuti i deriti no d\xe0i inte sti T\xe8rmini."],title:"Aceso al Sito"},{content:["<strong>Link de Tersi.</strong> El Sito podar\xeca gaver link a siti web e servisi de tersi. Sti Link de Tersi no i xe soto el contro\u0142o de <strong><a target='_blank' href='/'>luiskr.com</a></strong>, e <strong><a target='_blank' href='/'>luiskr.com</a></strong> no el xe responsabi\u0142e par nissun Link de Tersi. <strong><a target='_blank' href='/'>luiskr.com</a></strong> te d\xe0 aceso a sti Link de Tersi so\u0142o come comodit\xe0 par ti, e no i revarda, aprova, monitora, sostie, garantisse o fa nissuna rappresentasion verso i Link de Tersi. Te d\xf2pare tuti i Link de Tersi al to rischio, e deve aplicar un \u0142ive\u0142o adeto de caute\u0142a e discrezion fazendolo. Co te s\xecche so vargun dei Link de Tersi, i t\xe8rmini e \u0142e po\u0142\xecteghe del terso aplicabi\u0142e i va\u0142e, ciapando \u0142e pr\xe0teghe de privacy e rancura dati del terso.","<strong>Altri Uxidori.</strong> Ogni uxidor del Sito el xe responsabi\u0142e so\u0142o par el so Conten\xf9 Uxidor. Parc\xe8 no contro\u0142\xe9o el Conten\xf9 Uxidor, te reconose e consente che no semo responsabi\u0142i par nissun Conten\xf9 Uxidor, sia d\xe0 da ti sia da altri. Te consente che <strong><a target='_blank' href='/'>luiskr.com</a></strong> no vegnar\xe0 responsabi\u0142e par nissuna p\xe8rdita o dano incontr\xe0 come risultato de ste interasion. Se ghe na disputa tra ti e vargun uxidor del Sito, no semo soto nissun ob\u0142igo de intrarghene.","Par via de sta scritura te \u0142ibere e descarge par sempre <strong><a target='_blank' href='/'>luiskr.com</a></strong> e i nostri funsionari, inpiegai, agenti, suxessori e asignatari da, e par via de sta scritura te rinunse e \u0142ascia, ogni e tuta disputa, rec\u0142amo, controversia, dimanda, derito, ob\u0142igo, responsabi\u0142it\xe0, asion e cauxa d'asion de ogni tipo e natura, che \u0142a xe nada o \u0142a nase diretamente o indiretamente da, o che \u0142a se \u0142iga diretamente o indiretamente a, el Sito, pasada, presente e futura. Se te se residente de \u0142a Ca\u0142ifornia, par via de sta scritura te rinunse a \u0142a sesion 1542 del codexe civi\u0142e ca\u0142ifornian in \u0142egame co quanto sora, che \u0142a dixe: 'na \u0142iberasion xenera\u0142e no \u0142a se stende a rec\u0142ami che'l creditore no lu conose o sospeta de \xe8sar in so favor a'l tenpo de far \u0142a \u0142iberasion, che se conos\xf9i da \u0142u o \u0142ea i deve aver inpegn\xe0 materia\u0142mente el so acordo co'l debitore.'","<strong>Cookie e Web Beacon.</strong> Come cualsiasi altro sito web, <a target='_blank' href='/'>luiskr.com</a> el d\xf2para 'cookie'. El consenso a d\xf2parar i cookie el vien dito a l'aceso al sito web e se aceptai sti cookie i vien doparai par rancurar informasion ciapando \u0142e preferense dei visitadori, e \u0142e p\xe0xene del sito web che'l visitador g\xe0 aced\xf9 o visit\xe0. \u0141'informasion \u0142a xe doparada par otimizar \u0142a esperiensa dei uxidori persona\u0142ixando el conten\xf9 de \u0142e nostre p\xe0xene web in base al tipo de navegador dei visitadori e/o altre informasion."],title:"Link de Tersi; Altri Uxidori"},{content:["El sito el xe d\xe0 so base 'come che'l xe' e 'come che'l xe dispon\xecbi\u0142e', e <strong><a target='_blank' href='/'>luiskr.com</a></strong> e i nostri fornidori i decl\xecna espresamente ogni e tuta garansia e condision de ogni tipo, espresa, inpl\xecsita o statutaria, ciapando tute \u0142e garansie o condision de comerciabi\u0142it\xe0, idoneit\xe0 a 'n scopo partico\u0142ar, t\xecto\u0142o, gojimento tranco, acuratesa, o no violasion. Nialtri e i nostri fornidori no fa\xe7io garansia che'l sito el sodisfar\xe0 i to requixiti, el vegnar\xe0 dispon\xecbi\u0142e sensa interusion, puntuale, seguro o sensa erori, o che'l vegnar\xe0 acur\xe0, affidabi\u0142e, sensa virus o altro codexe danoso, conpleto, \u0142ega\u0142e o seguro. Se \u0142a \u0142exi aplicabi\u0142e \u0142a richiede varguna garansia sul sito, tute ste garansie \u0142e xe \u0142imitae in durada a novanta (90) di da \u0142a data del primo uxo.","Varguna zurisdision no \u0142a permete \u0142e esclusion de garansie inpl\xecsite, par cui \u0142e esclusion sora podar\xeca no aplicarse a ti. Varguna zurisdision no \u0142a permete \u0142imitasion so cuanto che na garansia inpl\xecsita \u0142a dura, par cui \u0142a \u0142imitasion sora podar\xeca no aplicarse a ti."],title:"Disclaimer"},{content:["A \u0142a masima misura permet\xeca da \u0142a \u0142exi, in nissun caxo <strong><a target='_blank' href='/'>luiskr.com</a></strong> o i nostri fornidori vegnar\xe0 responsabi\u0142i verso ti o vargun terso par prof\xecti p\xe8rsi, dati p\xe8rsi, costi de aprovixionamento de produti sostitutivi, o vargun dano indireto, consequensia\u0142e, exenp\u0142are, incidenta\u0142e, specia\u0142e o punitivo che'l nase da o che'l se \u0142iga a sti t\xe8rmini o al to uxo, o incapasit\xe0 de d\xf2parar, el sito anca se <strong><a target='_blank' href='/'>luiskr.com</a></strong> el xe st\xe0 avix\xe0 de \u0142a posibi\u0142it\xe0 de sti dani. \u0141'aceso e l'uxo del sito i xe a to discrezion e rischio, e te vegnar\xe0 responsabi\u0142e so\u0142o par vargun dano al to dispoxitivo o sistema conputador, o p\xe8rdita de dati che ne nase.","A \u0142a masima misura permet\xeca da \u0142a \u0142exi, nonostante cualsiasi cossa contraria conten\xf9a chi, \u0142a nostra responsabi\u0142it\xe0 verso ti par vargun dano che'l nase da o che'l se \u0142iga a sto acordo, \u0142a vegnar\xe0 sempe \u0142imitada a 'n masimo de sincuanta do\u0142ari U.S. (u.s. $50). \u0141'existensa de pi de un rec\u0142amo no \u0142a slarga sto \u0142imite. Te consente che i nostri fornidori no i g\xe0 nissuna responsabi\u0142it\xe0 de tipo che'l nase da o che'l se \u0142iga a sto acordo.","Varguna zurisdision no \u0142a permete \u0142a \u0142imitasion o esclusion de responsabi\u0142it\xe0 par dani incidenta\u0142i o consequensia\u0142i, par cui \u0142a \u0142imitasion o esclusion sora podar\xeca no aplicarse a ti.","<strong>T\xe8rmino e Terminasion.</strong> Sojeto a sta Sesion, sti T\xe8rmini i restar\xe0 in piena forsa e efeto mentre te d\xf2pare el Sito. Pod\xe9o susp\xe9ndar o terminar i to deriti de d\xf2parar el Sito a vargun tenpo par vargun motivo a nostra discrezion, ciapando vargun uxo del Sito in violasion de sti T\xe8rmini. A \u0142a terminasion dei to deriti soto sti T\xe8rmini, el to Conto e el derito de ac\xe9dar e d\xf2parar el Sito i terminar\xe0 subito. Te cap\xecse che varguna terminasion del to Conto podar\xeca ciapar \u0142e scance\u0142asion del Conten\xf9 Uxidor \u0142ig\xe0 al to Conto dai nostri database vivi. <strong><a target='_blank' href='/'>luiskr.com</a></strong> no g\xe0 nissuna responsabi\u0142it\xe0 verso ti par varguna terminasion dei to deriti soto sti T\xe8rmini. Anca dopo che i to deriti soto sti T\xe8rmini i xe termin\xe0i, \u0142e dispoxision seguenti de sti T\xe8rmini \u0142e restar\xe0 in efeto: Sesion 2 fin a 2.5, Sesion 3 e Sesion 4 fin a 10."],title:"\u0141imitasion de Responsabi\u0142it\xe0"},{content:["<strong><a target='_blank' href='/'>luiskr.com</a></strong> el rispeta \u0142a propriet\xe0 inte\u0142etua\u0142e dei altri e domanda che i uxidori del nostro Sito i faga lo steso. In \u0142egame co'l nostro Sito, semo adot\xe0 e inplement\xe0 na po\u0142\xectega che \u0142a rispeta \u0142a \u0142exi sul copyright che \u0142a prov\xe9de a \u0142a rimosion de vargun materia\u0142e infrinjor e a \u0142a terminasion dei uxidori del nostro Sito on\u0142ine che i xe infrinjori repet\xeci de deriti de propriet\xe0 inte\u0142etua\u0142e, ciapando copyright. Se te cr\xe8 che un dei nostri uxidori el s\xeca, tra l'uxo del nostro Sito, \u0142icamente infrinjendo el copyright de n'\xf2para, e te v\xf2i far remover el materia\u0142e a\u0142egadamente infrinjor, \u0142e informasion seguenti in forma de not\xecfega scrita (par via de 17 U.S.C. \xa7 512(c)) i deva \xe8sar d\xe0i al nostro Agente Copyright desegn\xe0.<ul><li>\u0142a to firma f\xeczega o e\u0142etr\xf2nega;</li><li>identificasion de l'\xf2para(e) co copyright che te rec\u0142ame \xe8sar sta infrinje;</li><li>identificasion del materia\u0142e sui nostri servisi che te rec\u0142ame \xe8sar infrinjor e che te ne dimande de remover;</li><li>informasion sufisienti par permeterne de catar sto materia\u0142e;</li><li>el to indiriso, n\xf9maro de te\u0142efono e indiriso email;</li><li>na dichiarasion che te g\xe0 na credensa de bona f\xe9 che l'uxo del materia\u0142e oxet\xecbi\u0142e no el xe autorix\xe0 dal propietario del copyright, el so agente, o soto \u0142a \u0142exi; e</li><li>na dichiarasion che \u0142e informasion inte \u0142a not\xecfega i xe acur\xe0i, e soto p\xe8na de sperzuro, che te se o'l propietario del copyright a\u0142egadamente infrinjo o che te se autorix\xe0 a far par conto del propietario del copyright.</li></ul>","Varda che, par via de 17 U.S.C. \xa7 512(f), varguna misrappresentasion de fato materia\u0142e in na not\xecfega scrita \u0142a soto-met automaticamente \u0142a parte rec\u0142amante a responsabi\u0142it\xe0 par vargun dano, costo e onorario de avocato incontr\xe0 da nialtri in \u0142egame co \u0142a not\xecfega scrita e a\u0142egasion de infrinsion del copyright."],title:"Po\u0142\xectega del Copyright."},{content:["Sti T\xe8rmini i xe sojeti a revixion ocasiona\u0142e, e se fa\xe7io vargun canbiamento sostansia\u0142e, pod\xe9o avixarte mandandote 'n email a l'\xf9ltimo indiriso email che te ne g\xe0 d\xe0 e/o postando in vista na not\xecfega dei canbiamenti so'l nostro Sito. Te se responsabi\u0142e de darne el to indiriso email pi atua\u0142e. In caxo che l'\xf9ltimo indiriso email che te ne g\xe0 d\xe0 no \u0142o s\xeca va\u0142ido, \u0142a nostra expiedision de l'email che g\xe0 sta not\xecfega \u0142a constituisi na not\xecfega efetiva dei canbiamenti descriti inte \u0142a not\xecfega. Vargun canbiamento a sti T\xe8rmini i vegnar\xe0 efetivi a'l pi presto dei trenta (30) d\xec ca\u0142endario dopo \u0142a nostra expiedision de na not\xecfega email a ti o trenta (30) d\xec ca\u0142endario dopo \u0142a nostra posta de na not\xecfega dei canbiamenti so'l nostro Sito. Sti canbiamenti i vegnar\xe0 efetivi subito par i uxidori novi del nostro Sito. \u0141'uxo continuo del nostro Sito dopo \u0142a not\xecfega de sti canbiamenti \u0142a indicar\xe0 el to reconosimento de sti canbiamenti e acordo de \xe8sar vinco\u0142\xe0 dai t\xe8rmini e condision de sti canbiamenti. Reso\u0142usion de Dispute. Par piaser \u0142eze sto Acordo de Arbitro co atension. El xe parte del to contrato co <strong><a target='_blank' href='/'>luiskr.com</a></strong> e'l inpe\xf1a i to deriti. El g\xe0 procedure par ARBITRO VINCO\u0141ANTE OBLIGATORIO E RINUNSA ASION DE CLASSE.","<strong>Aplicabi\u0142it\xe0 del Acordo de Arbitro.</strong> Tuti i rec\u0142ami e dispute in \u0142egame co i T\xe8rmini o l'uxo de vargun produto o servisio d\xe0 da <strong><a target='_blank' href='/'>luiskr.com</a></strong> che no i poda \xe8sar res\xf2\u0142ti informa\u0142mente o inte \u0142a corte de rec\u0142ami pici i vegnar\xe0 res\xf2\u0142ti da arbitro vinco\u0142ante so base indivixua\u0142e soto i t\xe8rmini de sto Acordo de Arbitro. Ecezion fada che altro acord\xe0, tute \u0142e procedure de arbitro \u0142e vegnar\xe0 tegn\xf9e in inglexe. Sto Acordo de Arbitro el se aplica a ti e <strong><a target='_blank' href='/'>luiskr.com</a></strong>, e a varguna suxidiaria, afi\u0142iada, agente, inpieg\xe0, predecesore in interese, suxessore e asignatario, cuss\xec come tuti i uxidori autorix\xe0i o no autorix\xe0i o beneficiari de servisi o beni d\xe0i soto i T\xe8rmini.","<strong>Requixito de Not\xecfega e Reso\u0142usion Informa\u0142e de Dispute.</strong> Prima che vargun parte posa sercar arbitro, \u0142a parte deve prima mandar a l'altra parte na Not\xecfega de Disputa scrita descrivendo \u0142a natura e base del rec\u0142amo o disputa, e el rimedio richiesto. Na Not\xecfega a <strong><a target='_blank' href='/'>luiskr.com</a></strong> deve \xe8sar mandada a: Rua Hugo Costa Duarte, 32, APTO. 01, Caraj\xe1, Santana do Livramento (RS), BR. Dopo che \u0142a Not\xecfega \u0142a xe risiv\xf9a, ti e <strong><a target='_blank' href='/'>luiskr.com</a></strong> podare provar a res\xf2\u0142var el rec\u0142amo o disputa informa\u0142mente. Se ti e <strong><a target='_blank' href='/'>luiskr.com</a></strong> no res\xf2\u0142ve el rec\u0142amo o disputa dentro trenta (30) d\xec dopo che \u0142a Not\xecfega \u0142a xe risiv\xf9a, varguna parte podar\xeca tacar na procedure de arbitro. \u0141'importo de varguna oferta de acordo fata da varguna parte no podar\xeca \xe8sar reve\u0142\xe0 a l'arbitro fin a dopo che l'arbitro g\xe0 determin\xe0 l'importo del premio a'l cua\u0142e varguna parte \u0142a g\xe0 derito.","<strong>Rego\u0142e de Arbitro.</strong> \u0141'arbitro vegnar\xe0 ini\xe7i\xe0 tra l'American Arbitration Association, un fornid\xf2r de reso\u0142usion dispute alternative stabil\xeco che ofre arbitro come posto inte sta sesion. Se AAA no \u0142a xe dispon\xecbi\u0142e a arbitrar, \u0142e parte \u0142e se acordar\xe0 a s\xe8rzar un Fornid\xf2r ADR alternativo. \u0141e rego\u0142e del Fornid\xf2r ADR \u0142e gobernar\xe0 tuti i aspeti del arbitro ecezion fada che ste rego\u0142e \u0142e xe in conflito co i T\xe8rmini. \u0141e Rego\u0142e de Arbitro Consumador AAA che \u0142e goberna l'arbitro i xe dispon\xecbi\u0142i on\u0142ine a adr.org o ciamando AAA a 1-800-778-7879. \u0141'arbitro vegnar\xe0 condoto da un so\u0142o arbitro neutro. Vargun rec\u0142amo o disputa ndove l'importo tota\u0142e del premio serc\xe0 el xe manco de Diexe Mi\u0142a Do\u0142ari U.S. (US $10,000.00) podar\xeca \xe8sar res\xf2\u0142to tra arbitro vinco\u0142ante sensa conparision, a'l s\xe8rz de \u0142a parte che serca rimedio. Par rec\u0142ami o dispute ndove l'importo tota\u0142e del premio serc\xe0 el xe Diexe Mi\u0142a Do\u0142ari U.S. (US $10,000.00) o pi, el derito a un'udieza vegnar\xe0 determin\xe0 da \u0142e Rego\u0142e de Arbitro. Varguna udieza vegnar\xe0 tegn\xf9a inte 'n posto dentro 100 mi\u0142e da \u0142a to residensa, ecezion fada che te res\xecde fora dei Stati Un\xeci, e ecezion fada che \u0142e parte \u0142e se acorda altro. Se te res\xecde fora dei U.S., l'arbitro dar\xe0 a \u0142e parte preavixo rason\xe9vo\u0142e de \u0142a data, ora e posto de varguna udieza ora\u0142e. Vargun sentensa so'l premio rend\xf9 da l'arbitro podar\xeca \xe8sar entr\xe0 in varguna corte de conpetente zurisdision. Ogni parte \u0142a portar\xe0 i so costi e desborxi che nase da l'arbitro e \u0142a pagar\xe0 na parte ecuale de \u0142e tarife e costi del Fornid\xf2r ADR.","<strong>Rego\u0142e in pi par Arbitro Sensa Conparision.</strong> Se arbitro sensa conparision el xe e\u0142eto, l'arbitro vegnar\xe0 condoto via te\u0142efono, on\u0142ine e/o bas\xe0 so\u0142o so sumision scrite; \u0142a manera spez\xecfega vegnar\xe0 sern\xeca da \u0142a parte che ini\xe7ia l'arbitro. \u0141'arbitro no ciapar\xe0 nissuna conparision persona\u0142e de \u0142e parte o testimoni ecezion fada che \u0142e parte \u0142e se acorda altro.","<strong>\u0141imiti de Tenpo.</strong> Se ti o <strong><a target='_blank' href='/'>luiskr.com</a></strong> se persigue arbitro, \u0142a asion arbitra\u0142e deve \xe8sar ini\xe7iada e/o dimandada dentro el statuto de \u0142imitasion e dentro vargun termine inposto soto \u0142e Rego\u0142e AAA par el rec\u0142amo pertinente.","<strong>Autorit\xe0 de l'Arbitro.</strong> Se l'arbitro el xe ini\xe7i\xe0, l'arbitro desider\xe0 i deriti e responsabi\u0142it\xe0 de ti e <strong><a target='_blank' href='/'>luiskr.com</a></strong>, e \u0142a disputa no vegnar\xe0 conso\u0142idada co vargun altri argumenti o zont\xe0 co vargun altri casi o parte. L'arbitro g\xe0 l'autorit\xe0 de dar mosion dispoxitive de tuto o parte de vargun rec\u0142amo. L'arbitro g\xe0 l'autorit\xe0 de dar dani monetari, e de dar vargun rimedio o so\u0142ievo no monetario dispon\xecbi\u0142e a un individuo soto \u0142a \u0142exi aplicabi\u0142e, \u0142e Rego\u0142e AAA, e i T\xe8rmini. L'arbitro emetar\xe0 un premio scrito e na dichiarasion de desision descrivendo i rexultai esensia\u0142i e concluxion so i cua\u0142i el premio el xe bas\xe0. L'arbitro g\xe0 \u0142a stesa autorit\xe0 de dar so\u0142ievo so base indivixua\u0142e che un zudece inte na corte de \u0142exi g\xe0. El premio de l'arbitro el xe fina\u0142e e vinco\u0142ante so ti e <strong><a target='_blank' href='/'>luiskr.com</a></strong>.","<strong>Rinunsa a Xudisio co Xur\xeca.</strong> \u0141E PARTE PAR VIA DE STA SCRITURA I RINUNSA I SO DERITI COSTITUSIONA\u0141I E STATUTARI DE N\xc0R IN CORTE E AVER 'N XUDISIO DAVANTI A 'N XUDECE O 'NA XUR\xccA, e\u0142exendo inve\xe7e che tuti i rec\u0142ami e dispute i vegnar\xe0 res\xf2\u0142ti da arbitro soto sto Acordo de Arbitro. \u0141e procedure de arbitro i xe tipicamente pi \u0142imitae, pi efisienti e manco costose de \u0142e rego\u0142e aplicabi\u0142i inte na corte e i xe sojeti a revixion tanto \u0142imitada da na corte. In caxo che varguna litio vegnar\xe0 f\xf2ra tra ti e <strong><a target='_blank' href='/'>luiskr.com</a></strong> in varguna corte stata\u0142e o federa\u0142e inte na causa par anu\u0142ar o far v\xe8gnar un premio arbitra\u0142e o altro, TI E <strong><a target='_blank' href='/'>luiskr.com</a></strong> RINUNSIO TUTI I DERITI A UN XUDISIO CO XUR\xccA, e\u0142exendo inve\xe7e che \u0142a disputa \u0142a vegnar\xe0 res\xf2\u0142ta da un zudece.","<strong>Rinunsa a Asioni de Classe o Conso\u0142idae.</strong> Tuti i rec\u0142ami e dispute dentro l'ambito de sto acordo arbitra\u0142e i deve \xe8sar arbitr\xe0i o litig\xe0i so base indivixua\u0142e e no so base de classe, e rec\u0142ami de pi de un cliente o uxidor no i poda \xe8sar arbitr\xe0i o litig\xe0i insieme o conso\u0142idai co cue\u0142i de vargun altro cliente o uxidor.","<strong>Confidensia\u0142it\xe0.</strong> Tuti i aspeti de \u0142a procedure de arbitro i vegnar\xe0 strettamente confidensia\u0142i. \u0141e parte \u0142e consente a mantegnir \u0142a confidensia\u0142it\xe0 ecezion fada che \u0142a \u0142exi \u0142a richieda altro. Sto par\xe0grafo no impedir\xe0 a na parte de sumetar a na corte de \u0142exi varguna informasion nesesaria par far v\xe8gnar sto Acordo, far v\xe8gnar un premio arbitra\u0142e, o sercar so\u0142ievo inibitorio o ekuo.","<strong>Divisibi\u0142it\xe0.</strong> Se varguna parte o parte de sto Acordo de Arbitro \u0142e vegnar\xe0 cat\xe0 soto \u0142a \u0142exi \xe8sar inva\u0142ide o no ezekutibi\u0142i da na corte de conpetente zurisdision, alora sta parte o parte spez\xecfega no g\xe0 forsa e efeto e vegnar\xe0 separada e el resto del Acordo restar\xe0 in piena forsa e efeto.","<strong>Derito de Rinunsa.</strong> Varguno o tuti i deriti e \u0142imitasion posti inte sto Acordo de Arbitro i podar\xeca \xe8sar rinuns\xe0i da \u0142a parte contro \u0142a cua\u0142e el rec\u0142amo el xe aserito. Sta rinunsa no rinunsar\xe0 o inpe\xf1ar\xe0 nissuna altra parte de sto Acordo de Arbitro.","<strong>Sopravivensa del Acordo.</strong> Sto Acordo de Arbitro sopraviver\xe0 \u0142a terminasion del to \u0142egame co <strong><a target='_blank' href='/'>luiskr.com</a></strong>.","<strong>Corte de Rec\u0142ami Pici.</strong> Nonostante quanto sora, ti o <strong><a target='_blank' href='/'>luiskr.com</a></strong> podar\xeca portar un'asion indivixua\u0142e inte \u0142a corte de rec\u0142ami pici.","<strong>So\u0142ievo Ekuo de Emerxensa.</strong> Nonostante quanto sora, varguna parte podar\xeca sercar so\u0142ievo ekuo de emergensa davanti a na corte stata\u0142e o federa\u0142e par mantegnir el status quo in atexa de arbitro. Na richiesta de misure interinali no vegnar\xe0 riten\xf9a na rinunsa a vargun altro derito o ob\u0142igo soto sto Acordo de Arbitro.","<strong>Rec\u0142ami no Sojeti a Arbitro.</strong> Nonostante quanto sora, rec\u0142ami de difamasion, violasion de l'Computer Fraud and Abuse Act, e infrinsion o apropriasion inpropria de breveto, copyright, marca o segr\xecto comercia\u0142e de l'altra parte no vegnar\xe0 sojeti a sto Acordo de Arbitro.","In varguna sirconstansa ndove l'Acordo de Arbitro sora el permete a \u0142e parte de litigar inte na corte, \u0142e parte \u0142e consente a sometarse a \u0142a zurisdision persona\u0142e de \u0142e corti situate dentro Netherlands County, Ca\u0142ifornia, par sti fini.","El Sito podar\xeca \xe8sar sojeto a \u0142exi de contro\u0142o exportasion U.S. e podar\xeca \xe8sar sojeto a rego\u0142amentasion de exportasion o importasion in altri paexi. Te consente a no esportar, riesportar o trasfer\xecr, diretamente o indiretamente, vargun dato t\xe8cnego U.S. acuix\xeco da <strong><a target='_blank' href='/'>luiskr.com</a></strong>, o vargun produto che d\xf2para sti dati, in violasion de \u0142e \u0142exi o rego\u0142amentasion de exportasion dei Stati Un\xeci.","<strong><a target='_blank' href='/'>luiskr.com</a></strong> el xe situ\xe0 a l'indiriso inte \u0142a Sesion 10.8. Se te se residente de \u0142a Ca\u0142ifornia, te podare riportar rec\u0142ami a \u0142a Complaint Assistance Unit of the Division of Consumer Product of the California Department of Consumer Affairs contatando\u0142i par iscrito a 400 R Street, Sacramento, CA 95814, o via te\u0142efono a (800) 952-5210.","<strong>Comunicasion E\u0142etr\xf2neghe.</strong> \u0141e comunicasion tra ti e <strong><a target='_blank' href='/'>luiskr.com</a></strong> i d\xf2para mezi e\u0142etr\xf2neghi, sia che te d\xf2pare el Sito o te ne mande email, o sia che <strong><a target='_blank' href='/'>luiskr.com</a></strong> el poste not\xecfeghe so'l Sito o comuneghe co ti via email. Par fini contratua\u0142i, (a) te consente a ris\xecvar comunicasion da <strong><a target='_blank' href='/'>luiskr.com</a></strong> in forma e\u0142etr\xf2nega; e (b) te consente che tuti i t\xe8rmini e condision, acordi, not\xecfeghe, divu\u0142gasion e altre comunicasion che <strong><a target='_blank' href='/'>luiskr.com</a></strong> te d\xe0 e\u0142etr\xf2negamente \u0142e sodisfa vargun ob\u0142igo \u0142ega\u0142e che ste comunicasion \u0142e sodisfar\xeca se \u0142e fosre in iscritura carta dura.","<strong>Tuti i T\xe8rmini.</strong> Sti T\xe8rmini i costituise l'intero acordo tra ti e nialtri verso l'uxo del Sito. El nostro mancamento de eserxitar o far v\xe8gnar vargun derito o dispoxision de sti T\xe8rmini no operar\xe0 come rinunsa a sto derito o dispoxision. I t\xecto\u0142i de sesion inte sti T\xe8rmini i xe so\u0142o par comodit\xe0 e no i g\xe0 efeto \u0142ega\u0142e o contratua\u0142e. \u0141a paro\u0142a 'ciapando' \u0142a signifega 'ciapando sensa \u0142imitasion'. Se varguna dispoxision de sti T\xe8rmini \u0142a vegnar\xe0 riten\xf9a inva\u0142ida o no ezekutibi\u0142e, \u0142e altre dispoxision de sti T\xe8rmini \u0142e vegnar\xe0 no inpe\xf1ae e \u0142a dispoxision inva\u0142ida o no ezekutibi\u0142e vegnar\xe0 riten\xf9a modificada cus\xec da \xe8sar va\u0142ida e ezekutibi\u0142e a \u0142a masima misura permet\xeca da \u0142a \u0142exi. El to \u0142egame con <strong><a target='_blank' href='/'>luiskr.com</a></strong> el xe cue\u0142o de un contratista indipendente, e gnenca parte \u0142a xe agente o socio de l'altra. Sti T\xe8rmini, e i to deriti e ob\u0142ighi chi, no i poda \xe8sar asign\xe0i, sotocontrat\xe0i, de\u0142eg\xe0i o trasfer\xeci da ti sensa el consenso scrito in antixipo de <strong><a target='_blank' href='/'>luiskr.com</a></strong>, e vargun tentativo de asignasion, sotocontrato, de\u0142egasion o trasferimento in violasion de quanto sora vegnar\xe0 nu\u0142o e vodo. <strong><a target='_blank' href='/'>luiskr.com</a></strong> podar\xeca asignar \u0142iberamente sti T\xe8rmini. I t\xe8rmini e condision posti inte sti T\xe8rmini i vegnar\xe0 vinco\u0142anti so i asignatari.","<strong>\u0141a To Privacy.</strong> Par piaser \u0142eze \u0142a Po\u0142\xectega de \u0142a Privacy.","<strong>Informasion Copyright/Marca.</strong> Copyright \xa9. Tuti i deriti riserv\xe0i. Tuti i marchi, logo e marchi de servisio mostr\xe0i so'l Sito i xe nostra propriet\xe0 o propriet\xe0 de altri tersi. No te se permetio de d\xf2parar sti Marchi sensa el nostro consenso scrito in antixipo o el consenso de sto terso che podar\xeca \xe8sar propietario dei Marchi."],title:"Xenera\u0142e"},{content:["<a target='_blank' href='https://github.com/LuisKrotz/luiskr.com-V3' rel='noopener'>Vargun fork podar\xeca \xe8sar fato via github, soto \u0141icensa MIT, doparando sto \u0142ink.</a>","<a target='_blank' href='https://github.com/LuisKrotz/luiskr.com-V2' rel='noopener'>Vargun fork de \u0142a version precedente del me sito web podar\xeca \xe8sar fato doparando sto \u0142ink.</a>"],title:"Repoxitorio"},{content:["Email:<a target='_blank' href='mailto:luis.krotz@gmail.com'>luis.krotz@gmail.com</a>","Te\u0142efono:<a target='_blank' href='tel:+55(51) 982-274-782'>+55 51 982-274-782</a>"],title:"Informasion de Contato"}],title:"Condision de Uxo"},"not-found":{title:"\ud83d\udc7d, \ud83d\udc7e, \ud83d\udc79, \ud83e\udd21, \ud83d\udc7b || \ud83e\udd16.<br>Tuti se perde de tanto in tanto.",link:"Back to the main page."},"star-field":{title:"Canpo Ste\u0142are",instructions:"Istrussioni",systemBoot:"Avio Sistema",hint:"Strasina par esplorar \xb7 Scori par el zoom \xb7 Se\u0142esiona un corpo par \u0142a so storia",explore:"Carta Ste\u0142are",solar:"Sistema So\u0142are",milkyWay:"Via Lata",nebulae:"Nebo\u0142ose",galaxies:"Ga\u0142asie",satellite:"Satelit",screenshot:"Fa Screenshot",overview:"Panoramica",loading:"Cargando\u2026",source:"Fonte",star:"Ste\u0142a",planet:"Pianeta",dwarfPlanet:"Pianeta Nano",asteroid:"Asteroide",comet:"Comet\xe0",moon:"\u0141una",blackHole:"Buco Nero",system:"Sistema Ste\u0142are",nebula:"Nebo\u0142osa",galaxy:"Ga\u0142asia",cluster:"Ammasso",acquired:"Dati acquis\xeci",translated:"Tradoto",search:"Serca inte\u2019l catalogo\u2026",exoplanet:"Esopianeta",dso:"Ogeto del \xe7\xe8\u0142o profondo",catalog:"Cata\u0142ogo profondo",records:"record",loadMore:"Kag\xe9it aa",searching:"Catalog s\u2019\xe1a a kkwjeit\u2026",magnitude:"Magnit\xf9dine aparente",distance:"Distansa",spectralType:"Tipo spetra\u0142e",constellation:"Coste\u0142asion",designation:"Designasion",hostStar:"Ste\u0142a ospite",dsoType:"Tipo de ogeto",discovery:"Scoverta",redshift:"Spostamento verso el roso",coordinates:"Posision e\u0142iosentrica",registry_star:"Catalogued kotl\u2019\xe9ikw",registry_star_about:"Na ste\u0142a vera del cata\u0142ogo HYG (Hipparcos/Gliese/Tycho) \u2014 posision, magnit\xf9dine e clase spetra\u0142e da \u0142a astrometr\xeca publeg\xe0.",registry_exoplanet:"Esopianeta conferm\xe0",registry_exoplanet_about:"Un pianeta conferm\xe0 del NASA Exoplanet Archive, mostr\xe0 a \u0142a posision misur\xe0 de \u0142a s\xf3 ste\u0142a ospite.",registry_dso:"Ogeto del \xe7\xe8\u0142o profondo catalog\xe0",registry_dso_about:"Un ogeto del \xe7\xe8\u0142o profondo NGC/IC del cata\u0142ogo OpenNGC \u2014 ga\u0142asia, grupe\u0142o o nebu\u0142osa; distansa dal redshift quando dispon\xecbi\u0142e.",localGroup:"Grup Local",hierarchy:"Ierarchia Cosmic\u0103",dwarfGalaxy:"Ga\u0142asia Pitic\u0103",structure:"Structur\u0103 Cosmic\u0103",belt:"Cintura",disclaimer:"Sto esperimento no simula \u0142e distanse spasia\u0142i ve\u0263e, n\xe9 \u0142a par\xe9nsa o \u0142e forme ve\u0263e dei ogeti. \u0141a disposision \u0142a ze pensada par navegar e par prexentar \u0142e informasion in modo interativo \u2014 no \u0142a rifl\xe8te dati ve\u0263i.",description:"Canpo ste\u0142are WebGL interativo \u2014 vo\u0142a par el Sistema So\u0142are, \u0142e ste\u0142e visine, nebu\u0142ose e ga\u0142asie."},"earth-playground":{title:"Tera\u0142udo",experienceSettings:"Inpostasion Esperiensa",systemBoot:"Avio Sistema",camera:"C\xe0mara",fov:"FOV",rotateSpeed:"Ve\u0142osit\xe0 de Rotasion",autoRotate:"Auto-Rotasion",resetView:"Rexero Vista",earth:"Tera",spinSpeed:"Ve\u0142osit\xe0 de Xiro",engine:"Inpostasion Motore",waterMetalness:"Meta\u0142icit\xe0 A\u0107ua",terrain:"Inpostasion Tereno",bumpScale:"Sca\u0142a M\xe0pa Bump",selfShadow:"Intensit\xe0 Ombra Propia",selfShadowOff:"Offset Ombra Propia",postFx:"Post E\u0142aborasion",bloom:"Bloom",bloomStr:"Forza Bloom",bloomRadius:"Raio Bloom",bloomThreshold:"S\xf3ja Bloom",vignette:"Vi\xf1eta",vigDarkness:"Scurit\xe0",vigOffset:"Offset",chromaticAb:"Aberasion Crom\xe0tega",caStrength:"Forza AC",filmGrain:"Grana Fi\u0142m",color:"Co\u0142or",contrast:"Contrasto",saturation:"Saturasion",blackLevel:"\u0141ive\u0142o Nero",sunAutoRotate:"Auto-Rotasion So\u0142e",displayDebug:"Mostra e Debug",showStats:"Mostra Stat\xecsteghe",resScale:"Sca\u0142a Risolusion",screenshot:"Tira Screenshot",copyConstants:"Copia Costanti GUI",position:"Posision (Atua\u0142e)",target:"Bersagio (Atua\u0142e)",defaults:{waterMetalness:0,bumpScale:5,selfShadow:1,selfShadowOff:.002,bloom:!1,bloomStr:.1,bloomRadius:.3,bloomThreshold:.9,vignette:!1,vigDarkness:1,vigOffset:.5,chromaticAb:!1,caStrength:.25,filmGrain:0,fov:45,autoRotate:!1,rotateSpeed:.05,spinSpeed:1,sunAutoRotate:!0,contrast:1,saturation:1.5,blackLevel:.015,resScale:1},description:"Playground WebGL interativo de \u0142a Tera \u2014 rego\u0142a teren, atmosfera, \u0142uze e post-e\u0142aborasion dal vivo."},license:{title:"Licensa P\xf9blica Mozilla 2.0",sections:[{title:"In merito a sto documento",content:["Sta p\xe0gina \u0142a conti\xe9n el testo conpleto e uficial de \u0142a Mozilla Public License 2.0 (MPL 2.0), \u0142a licensa co \u0142a cua\u0142e el c\xf2dese sorgente de sto sito el vien public\xe0. \u0141a licensa \u0142a xe na concesion mondia\u0142e, sensa royalty, v\xe0\u0142ida in tuti i paezi e teritori.","El testo ingl\xe9s el xe \u0142a version \u0142ega\u0142e uficia\u0142e. \u0141e traduzion de sta p\xe0gina in altre \u0142\xe9ngue \u0142e vien dae so\u0142o par comodit\xe0; se na traduzion \u0142a difarise da l'originale ingl\xe9s, prevale el testo ingl\xe9s."]},{title:"1. Definizion",content:["1.1. &quot;Contributore&quot; el v\xf2l dir ogni persona f\xeczega o xur\xecdega che crea, contribuise a \u0142a creasion o el poss\xecede Software Coverto.","1.2. &quot;Version del Contributore&quot; \u0142a v\xf2l dir \u0142a combinasion de \u0142e Contribuzion de altri (se ghe ne xe) dopr\xe0e da un Contributore e \u0142a Contribuzion de que\u0142o specifego Contributore.","1.3. &quot;Contribuzion&quot; \u0142a v\xf2l dir Software Coverto de un Contributore in partico\u0142are.","1.4. &quot;Software Coverto&quot; el v\xf2l dir Forma de C\xf2dese Sorgente a \u0142a cua\u0142e el Contributore inizia\u0142e el ga tac\xe0 l'avixo de l'A\u0142eg\xe0 A, \u0142a Forma Esegu\xecbi\u0142e de cua Forma de C\xf2dese Sorgente e \u0142e Modifiche de cua Forma de C\xf2dese Sorgente, incluzendo in ogni cazo parte de \u0142a stesa.","1.5. &quot;Incompat\xecbi\u0142e co \u0141icense Secondarie&quot; el v\xf2l dir (a) che el Contributore inizia\u0142e el ga tac\xe0 al Software Coverto l'avixo descrito in l'A\u0142eg\xe0 B; o (b) che el Software Coverto el xe sta met\xf9o a dispozision soto i termini de \u0142a version 1.1 o presedente de \u0142a \u0141icensa, ma no anca soto i termini de na \u0141icensa Secondaria.","1.6. &quot;Forma Esegu\xecbi\u0142e&quot; \u0142a v\xf2l dir calsiasi forma de \u0142a \xf2para difarente da \u0142a Forma de C\xf2dese Sorgente.","1.7. &quot;\xd2para Pi\xf9 Granda&quot; \u0142a v\xf2l dir n'\xf2para che \u0142a combina Software Coverto co altro materia\u0142e, in un fi\u0142e o fi\u0142e separai, che no \u0142a xe Software Coverto.","1.8. &quot;\u0141icensa&quot; \u0142a v\xf2l dir sto documento.","1.9. &quot;\u0141icensabi\u0142e&quot; el v\xf2l dir vere el drito de concedere, inte \u0142a m\xe0sima misura pus\xecbi\u0142e, sia a el momento de \u0142a concesion inizia\u0142e sia dopo, calsiasi e tuti i driti trasmisi da sta \u0141icensa.","1.10. &quot;Modifiche&quot; \u0142e v\xf2l dir calsiasi de \u0142e seventi: (a) calsiasi fi\u0142e in Forma de C\xf2dese Sorgente che'l rezulta da na zunta a, na scanse\u0142asion da o na modifica de \u0142a conponente del Software Coverto; o (b) calsiasi fi\u0142e novo in Forma de C\xf2dese Sorgente che'l conti\xe9n Software Coverto.","1.11. \u0141e &quot;Reivindicasion de Breveto&quot; de un Contributore \u0142e v\xf2l dir calsiasi reivindicasion de breveto, incluzendo, sensa limitasion, \u0142e reivindicasion de metodo, procezo e aparechio, in calsiasi breveto \u0141icensabi\u0142e da cue\u0142o Contributore che'l sar\xeca viol\xe0, se no fuse par \u0142a concesion de \u0142a \u0141icensa, dal produre, doparare, vendere, ofrire in vendita, far produre, inportare o trasferire de \u0142e so Contribuzion o de \u0142a so Version del Contributore.","1.12. &quot;\u0141icensa Secondaria&quot; \u0142a v\xf2l dir \u0142a GNU General Public License, Version 2.0, \u0142a GNU Lesser General Public License, Version 2.1, \u0142a GNU Affero General Public License, Version 3.0, o calsiasi version sucesiva de cue\u0142e \u0142icense.","1.13. &quot;Forma de C\xf2dese Sorgente&quot; \u0142a v\xf2l dir \u0142a forma de \u0142a \xf2para prefer\xeca par far modifiche.","1.14. &quot;Ti&quot; (o &quot;To&quot;) el v\xf2l dir na persona f\xeczega o xur\xecdega che \u0142a ez\xe8rcita driti soto sta \u0141icensa. Par \u0142e persone xur\xecdeghe, &quot;Ti&quot; el incl\xf9de calsiasi entit\xe0 che \u0142a contro\u0142a, \u0142a xe contro\u0142\xe0 da, o \u0142a xe soto contro\u0142o com\xf9n co Ti. Par i scopi de sta definizion, &quot;contro\u0142o&quot; el v\xf2l dir (a) el poder, direto o indireto, de dirizere \u0142a direzion o \u0142a jestion de cue\u0142a entit\xe0, sia par contrato sia in altro modo, o (b) \u0142a propiet\xe0 de pi\xf9 del sincuanta par sento (50%) de \u0142e quote in sirco\u0142asion o \u0142a propiet\xe0 beneficiaria de cue\u0142a entit\xe0."]},{title:"2. Concesion e condizion de \u0142a \u0141icensa",content:["2.1. Concesion \u2014 Ogni Contributore te concede par \u0142a prexente na \u0142icensa mondia\u0142e, sensa royalty e no-escluziva: (a) soto driti de propriet\xe0 inte\u0142etua\u0142e (difarenti da breveto o marca) \u0141icensabi\u0142i da cue\u0142o Contributore par doparare, reprodure, metere a dispozision, modificare, exibire, ezeguire, distribuire e sfrutare in altro modo \u0142e so Contribuzion, sia sensa modifiche, co Modifiche, o come parte de n'\xd2para Pi\xf9 Granda; e (b) soto Reivindicasion de Breveto de cue\u0142o Contributore par produre, doparare, vendere, ofrire in vendita, far produre, inportare e trasferire in altro modo \u0142e so Contribuzion o \u0142a so Version del Contributore.","2.2. Data de eficasia \u2014 \u0141e \u0142icense concese inte \u0142a Sezion 2.1 in merito a calsiasi Contribuzion \u0142e entra in vigor par ogni Contribuzion a \u0142a data in cue\u0142a che el Contributore \u0142a distribuise par \u0142a prima volta.","2.3. Limitazion de l'ambito de \u0142a concesion \u2014 \u0141e \u0142icense concese inte \u0142a Sezion 2 \u0142e xe i so\u0142i driti concesi soto sta \u0141icensa. Nissun drito o \u0142icensa zontivo el vegnar\xe0 fora da \u0142a distribuzion o \u0142icensiamento del Software Coverto soto sta \u0141icensa. Fermo stando \u0142a Sezion 2.1(b) de sora, nissuna \u0142icensa de breveto \u0142a xe concesa da un Contributore: (a) par calsiasi c\xf2dese che un Contributore el gabia rem\xf2o dal Software Coverto; o (b) par violazion cauz\xe0e da: (i) to modifiche e cue\u0142e de tersi del Software Coverto, o (ii) \u0142a combinasion de \u0142e so Contribuzion co altro software (salvo come parte de \u0142a so Version del Contributore); o (c) soto Reivindicasion de Breveto viol\xe0e dal Software Coverto in asensa de \u0142e so Contribuzion. Sta \u0141icensa no \u0142a concede nissun drito so marche, marche de servizio o \u0142oghi de nissun Contributore (salvo inte \u0142a misura necesaria par sodisfare i requiziti de avixo de \u0142a Sezion 3.4).","2.4. \u0141icense sucesive \u2014 Nissun Contributore el fa concesion zontive come rezultato de \u0142a to scelta de distribuire el Software Coverto soto na version sucesiva de sta \u0141icensa (varda Sezion 10.2) o soto i termini de na \u0141icensa Secondaria (se permeso dai termini de \u0142a Sezion 3.3).","2.5. Dichiarasion \u2014 Ogni Contributore el dichiara de credere che \u0142e so Contribuzion \u0142e sia \u0142e so creazion orixina\u0142i o che'l g\xe0bia driti suficienti par concedere i driti so \u0142e so Contribuzion che sta \u0141icensa \u0142a trasmete.","2.6. Uso xusto \u2014 Sta \u0141icensa no \u0142a ga intenzion de limitare nissun drito che ti g\xe0bi soto \u0142e dotrine aplicabi\u0142i de fair use, fair dealing o altri ecuiva\u0142enti del drito d'autore.","2.7. Condizion \u2014 \u0141e Sezion 3.1, 3.2, 3.3 e 3.4 \u0142e xe condizion de \u0142e \u0142icense concese inte \u0142a Sezion 2.1."]},{title:"3. Responsabi\u0142it\xe0",content:["3.1. Distribuzion de \u0142a Forma de C\xf2dese Sorgente \u2014 Calsiasi distribuzion del Software Coverto in Forma de C\xf2dese Sorgente, incluzendo \u0142e Modifiche che ti fe o a \u0142e cua\u0142i ti contribuisi, \u0142a ga da \xe8ser fata soto i termini de sta \u0141icensa. Ti ga da informare i destinatari che \u0142a Forma de C\xf2dese Sorgente del Software Coverto \u0142a xe rego\u0142\xe0 dai termini de sta \u0141icensa e come \u0142e p\xf2l otegner na copia de sta \u0141icensa. Ti no pol provare a alterare o limitare i driti dei destinatari so \u0142a Forma de C\xf2dese Sorgente.","3.2. Distribuzion de \u0142a Forma Esegu\xecbi\u0142e \u2014 Se ti distribuisi Software Coverto in Forma Esegu\xecbi\u0142e, alora: (a) cue\u0142o Software Coverto el ga da \xe8ser met\xf9o a dispozision anca in Forma de C\xf2dese Sorgente, come descrito inte \u0142a Sezion 3.1, e ti ga da informare i destinatari de \u0142a Forma Esegu\xecbi\u0142e de come \u0142e p\xf2l otegner na copia de cue\u0142a Forma de C\xf2dese Sorgente par mezi rason\xe9vo\u0142i e in maniera tempestiva, a un costo no superior a el costo de distribuzion al destinatario; e (b) ti pol distribuire cue\u0142a Forma Esegu\xecbi\u0142e soto i termini de sta \u0141icensa, o soto\u0142icensiarla a termini difarenti, a condizion che \u0142a \u0142icensa de \u0142a Forma Esegu\xecbi\u0142e no \u0142a tente de limitare o alterare i driti dei destinatari so \u0142a Forma de C\xf2dese Sorgente soto sta \u0141icensa.","3.3. Distribuzion de n'\xd2para Pi\xf9 Granda \u2014 Ti pol creare e distribuire n'\xd2para Pi\xf9 Granda a termini de to scelta, a condizion che ti sodisfi anca i requiziti de sta \u0141icensa par el Software Coverto. Se l'\xd2para Pi\xf9 Granda \u0142a xe na combinasion del Software Coverto co n'\xf2para rego\u0142\xe0 da una o pi\xf9 \u0141icense Secondarie, e el Software Coverto no'l xe Incompat\xecbi\u0142e co \u0141icense Secondarie, sta \u0141icensa te permete inoltre de distribuire cue\u0142o Software Coverto soto i termini de cue\u0142a cue\u0142e \u0141icense Secondarie, in modo che el destinatario de l'\xd2para Pi\xf9 Granda el posa, a so scelta, continuar a distribuire el Software Coverto soto i termini sia de sta \u0141icensa sia de cue\u0142a cue\u0142e \u0141icense Secondarie.","3.4. Avixi \u2014 Ti no pol remuovere n\xe8 alterare \u0142a sostansa de calsiasi avixo de \u0142icensa (incluzendo avixi de drito d'autore, avixi de breveto, cl\xe0uzo\u0142e de esoner de garansia o limitazion de responsabi\u0142it\xe0) conten\xf9o inte \u0142a Forma de C\xf2dese Sorgente del Software Coverto, salvo che ti pol alterare calsiasi avixo de \u0142icensa inte \u0142a misura necesaria par corezere inesatense fatua\u0142i conos\xf9e.","3.5. Aplicazion de termini zontivi \u2014 Ti pol s\xe8rzere de ofrire, e richiedere na tarifa par, garansia, suporto, indenit\xe0 o oblegazion de responsabi\u0142it\xe0 a uno o pi\xf9 destinatari del Software Coverto. Par\xf2, ti pol far\u0142o so\u0142o in to nome e no in nome de nissun Contributore. Ti ga da rendere aso\u0142utamente ciaro che calsiasi garansia, suporto, indenit\xe0 o oblegazion de responsabi\u0142it\xe0 \u0142a vien ofr\xeca so\u0142o da ti, e ti aceti de indenizare ogni Contributore par calsiasi responsabi\u0142it\xe0 in cue\u0142a che cue\u0142o Contributore el incorra come rezultato dei termini de garansia, suporto, indenit\xe0 o responsabi\u0142it\xe0 che ti ofri. Ti pol incl\xf9dere cl\xe0uzo\u0142e de esoner de garansia e limitazion de responsabi\u0142it\xe0 zontive specifeghe de calsiasi xurisdision."]},{title:"4. Inposibi\u0142it\xe0 de conformente par \u0142eje o rego\u0142amento",content:["Se te xe inpos\xecbi\u0142e conformarte a calsiasi dei termini de sta \u0141icensa in merito a parte o a \u0142a totalit\xe0 del Software Coverto a cauza de na \u0142eje, un ordine xudisiario o un rego\u0142amento, alora ti ga da: (a) conformarte ai termini de sta \u0141icensa inte \u0142a m\xe0sima misura pus\xecbi\u0142e; e (b) descrivere \u0142e limitazion e el c\xf2dese che \u0142e coinvolze. Cue\u0142a descrision \u0142a ga da \xe8ser met\xf9a in un fi\u0142e de testo a\u0142eg\xe0 a tutte \u0142e distribuzion del Software Coverto in Forma de C\xf2dese Sorgente. Salvo inte \u0142a misura proib\xeca da \u0142a \u0142eje o dal rego\u0142amento, cue\u0142a descrision \u0142a ga da \xe8ser suficentemente deta\u0142i\xe0 perch\xe9 un destinatario de abi\u0142it\xe0 ordinaria el posa capirla."]},{title:"5. Rezoluzion",content:["5.1. I driti concesi soto sta \u0141icensa i xe stinsi automaticamente se ti incontri calsiasi dei so termini. Par\xf2, se ti torni a conformarte, i driti concesi da un Contributore partico\u0142are soto sta \u0141icensa i xe restabi\u0142ii (a) provizoriamente, a manco che e fintanto che cue\u0142o Contributore no'l rezolve esplicitamente e definitivamente \u0142e to concesion, e (b) in maniera continua, se cue\u0142o Contributore no'l te notifica \u0142a violasion par mezi rason\xe9vo\u0142i prima che 60 zorni i sia pasai da cuando ti xe torn\xe0 a conformarte. Inoltre, \u0142e to concesion da un Contributore partico\u0142are \u0142e xe restabi\u0142ie in maniera continua se cue\u0142o Contributore te notifica \u0142a violasion par mezi rason\xe9vo\u0142i, se \u0142a xe \u0142a prima volta che ti riz\xe8vi na notifica de violasion de sta \u0141icensa da cue\u0142o Contributore, e se ti torni a conformarte prima che 30 zorni i sia pasai da \u0142a ricevuta de \u0142a notifica.","5.2. Se ti inicii un contenziozo contro calsiasi entit\xe0 asertando na reivindicasion de violasion de breveto (escluzendo \u0142e azion de xudisio dichiarativo, \u0142e demande riconvenziona\u0142i e \u0142e demande inroz\xe0e) afirmando che na Version del Contributore \u0142a infrinze diretamente o indiretamente calsiasi breveto, alora i driti concesi a ti da calsiasi e tuti i Contributori par el Software Coverto soto \u0142a Sezion 2.1 de sta \u0141icensa i xe stinsi.","5.3. In cazo de rezoluzion soto \u0142e Sezion 5.1 o 5.2 de sora, tuti i contrati de \u0142icensa par utente fina\u0142e (escluzendo distributori e rivenditori) che i xe stai va\u0142idamente concesi da ti o dai to distributori soto sta \u0141icensa prima de \u0142a rezoluzion i soravive a cue\u0142a."]},{title:"6. Esoner de garansia",content:["EL SOFTWARE COVERTO EL VIEN FORN\xccO SOTO STA \u0141ICENSA &quot;CUAL EL XE&quot;, SENSA GARANSIA DE NISSUN TIPO, SIA ESPRESA, IMPL\xccSITA O LEGA\u0141E, INCLUZENDO, SENSA LIMITAZION, \u0141E GARANSIE CHE EL SOFTWARE COVERTO EL XE SENSA DIFETI, COMERZIA\u0141E, IDONEO A UN SCOPO PARTICO\u0141ARE O NO-VIO\u0141ANTE. TUTO EL RIZICO IN MERITO A \u0141A CUA\u0141IT\xc0 E A \u0141A PRESTAZION DEL SOFTWARE COVERTO EL XE TUO. SE CALSIASI SOFTWARE COVERTO EL REZULTASE DIFETUZO IN CALSIASI ASPETo, TI (E NO NISSUN CONTRIBUTORE) SOSTIENI EL COSTO DE CALSIASI MANUTENZION, RIPARAZION O COREZION NECESARIA. STO ESONER DE GARANSIA EL COSTITUISE PARTE ESENZIA\u0141E DE STA \u0141ICENSA. NISSUN USO DEL SOFTWARE COVERTO EL XE AUTORIZ\xc0 SOTO STA \u0141ICENSA SE NO SOTO STO ESONER."]},{title:"7. Limitazion de responsabi\u0142it\xe0",content:["IN NISSUN CASO E SOTO NISSUNA TEORIA \u0141EGA\u0141E, SIA RESPONSABI\u0141IT\xc0 ESTRACONTRATUA\u0141E (INCLUZENDO \u0141A NEZ\u0141IZENSA), CONTRATUA\u0141E O IN ALTRO MODO, NISSUN CONTRIBUTORE, O CHISIA CHE DISTRIBUISE EL SOFTWARE COVERTO COME PERMESO DE SORA, EL SAR\xc0 RESPONSABI\u0141E VERSO TI PAR DANI DIRETI, INDIRETI, SPEZIA\u0141I, INCIDENTA\u0141I O CONSECUENTI DE CALSIASI TIPO, INCLUZENDO, SENSA LIMITAZION, DANI PAR \u0141UCRO CEZANTE, PERDITA DE CLIENTE\u0141A, INTERUZION DE \u0141AVORO, GUASTO O MALFUNZIONAMENTO INFORM\xc0TEGO, O CALSIASI ALTRO DANO O PERDITA COMERZIA\u0141E, ANCA SE CUE\u0141A PARTE \u0141A FUSE STA INFORM\xc0 DE \u0141A POSIBI\u0141IT\xc0 DE CUE\u0141I DANI. STA LIMITAZION DE RESPONSABI\u0141IT\xc0 NO \u0141A SE APLICAR\xc0 A \u0141A RESPONSABI\u0141IT\xc0 PAR MORTE O \u0141EZION PERSONA\u0141I DERIVANTI DA \u0141A NEZ\u0141IZENSA DE CUE\u0141A PARTE INTE \u0141A MISURA IN CUE\u0141A CHE \u0141A \u0141EJE APLICABI\u0141E \u0141A PROIBISE CUE\u0141A LIMITAZION. CUE\u0141E XURISDISION NO \u0141E PERMETE \u0141'ESCLUZION O \u0141IMITAZION DE DANI INCIDENTA\u0141I O CONSECUENTI, PAR CUE\u0141O STA ESCLUZION E LIMITAZION \u0141E PODAR\xccA NO APLICARSE A TI."]},{title:"8. Contenziuzi",content:["Calsiasi contenziozo re\u0142ativo a sta \u0141icensa el pol \xe8ser prom\xf2o so\u0142o vanti i tribuna\u0142i de \u0142a xurisdision andove el conven\xf9o el ga \u0142a so sede prinsipale, e cue\u0142o contenziozo el sar\xe0 rego\u0142\xe0 da \u0142e \u0142eji de cue\u0142a xurisdision, sensa referimento a \u0142e so norme so conflito de \u0142eji. Ninte inte \u0142a Sezion impedir\xe0 \u0142a capacit\xe0 de na parte de propornere demande riconvenziona\u0142i o inroz\xe0e."]},{title:"9. Varie",content:["Sta \u0141icensa \u0142a raprezenta l'acordo conpleto re\u0142ativo a el so ogeto. Se calsiasi dispozision de sta \u0141icensa \u0142a xe xudic\xe0 inat\xf3a, cue\u0142a dispozision \u0142a sar\xe0 reform\xe0 so\u0142o inte \u0142a misura necesaria par renderla esegebi\u0142e. Nissuna \u0142eje o rego\u0142amento che'l stabilise che \u0142a \u0142\xe9ngua de un contrato \u0142a ga da \xe8ser interpret\xe0 contro el redator \u0142a sar\xe0 dopar\xe0 par interpretare sta \u0141icensa contro un Contributore."]},{title:"10. Version de \u0142a \u0141icensa",content:["10.1. Version nove \u2014 \u0141a Mozilla Foundation \u0142a xe l'aministradora de \u0142a \u0142icensa. Salvo come previsto inte \u0142a Sezion 10.3, nissun altro che l'aministradora de \u0142a \u0142icensa el ga drito de modificare o publicare version nove de sta \u0141icensa. A ogni version el sar\xe0 asen\xe0 un numaro de version distintivo.","10.2. Efeto de \u0142e version nove \u2014 Ti pol distribuire el Software Coverto soto i termini de \u0142a version de \u0142a \u0141icensa soto \u0142a cua\u0142e ti ga orixina\u0142iamente riz\xe9v\xf9o el Software Coverto, o soto i termini de calsiasi version sucesiva public\xe0 da l'aministradora de \u0142a \u0142icensa.","10.3. Version modific\xe0e \u2014 Se ti crei software no rego\u0142\xe0 da sta \u0141icensa e ti v\xe8i creare na \u0142icensa nova par cue\u0142o software, ti pol creare e doparare na version modific\xe0 de sta \u0141icensa se ti rinomena \u0142a \u0142icensa e remuovi calsiasi referimento a el nome de l'aministradora de \u0142a \u0142icensa (salvo par dir che cue\u0142a \u0142icensa modific\xe0 \u0142a difarise da sta \u0141icensa).","10.4. Distribuzion de Forma de C\xf2dese Sorgente Incompat\xecbi\u0142e co \u0141icense Secondarie \u2014 Se ti s\xe8lzi de distribuire Forma de C\xf2dese Sorgente Incompat\xecbi\u0142e co \u0141icense Secondarie soto i termini de sta version de \u0142a \u0141icensa, el ga da \xe8ser tac\xe0 l'avixo descrito in l'A\u0142eg\xe0 B de sta \u0141icensa."]},{title:"A\u0142eg\xe0 A \u2014 Avixo de \u0142icensa de \u0142a Forma de C\xf2dese Sorgente",content:["Sta Forma de C\xf2dese Sorgente \u0142a xe sogeta ai termini de \u0142a Mozilla Public License, v. 2.0. Se na copia de \u0142a MPL no \u0142a xe sta distribu\xeca co sto fi\u0142e, ti pol otegner na a https://mozilla.org/MPL/2.0/.","Se no'l xe pos\xecbi\u0142e o conveniente metere l'avixo in un fi\u0142e partico\u0142are, ti pol incl\xf9dere l'avixo in un posto (come un fi\u0142e LICENSE in na cart\xe8\u0142a re\u0142evante) andove un destinatario el sercar\xeca probabilmente.","Ti pol zontare avixi zontivi e ezati de propiet\xe0 de drito d'autore."]},{title:"A\u0142eg\xe0 B \u2014 Avixo de &quot;Incompat\xecbi\u0142e co \u0141icense Secondarie&quot;",content:["Sta Forma de C\xf2dese Sorgente \u0142a xe &quot;Incompat\xecbi\u0142e co \u0141icense Secondarie&quot;, come defin\xeca da \u0142a Mozilla Public License, v. 2.0."]}]},animations:{title:"Riferimento Animassion",description:"Tute le animazion del sito, descrite \u2014 elemento, movimento, ativazion, tecnologia e scopo \u2014 par letori, tecnologie assistive e agenti IA."}}}}))()}var a,i;import{n as o,t as r}from"./rolldown-runtime-CKc5dgUC.js";a=o({default:()=>i});export{e as n,a as t};